programs.sol:
"""A lexical detector for underscore markers and quoted-container syntax.

An isolated double underscore has a large negative response. A following
separator (a closing name marker) or a long underscore rule is much weaker.
Private-name prefixes, percent signs, quoted container openings, Python
prompts, and solid block bars receive smaller negative predictions. The
constructor suffix init__( instead receives a small positive prediction;
TeX subscript openings are also weakly positive. All other tokens get zero.
Only the previous token in the same document is consulted for context.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip()
    symbolic = text and not any(c.isalnum() for c in text)
    if symbolic and '__' in text:
        if token.endswith('\n'):
            value = -1.5
        elif text.rstrip('_') == '':
            if len(text) == 2:
                value = -6.1 if token.startswith(' ') else -6.6
                if len(previous) > 2 and set(previous) == {'_'}:
                    value = -3.0
                elif token.startswith(' ') and previous == 'def':
                    value = -6.7
            else:
                value = -1.3 if len(text) >= 16 else -0.9
        elif text.endswith('__'):
            if '.' in text:
                value = -5.1
            elif '/' in text:
                value = -6.35
            elif '"' in text or "'" in text:
                value = -3.8
            else:
                value = -4.4
        elif text == '__(':
            value = 0.65 if previous == 'init' else -3.0
        else:
            value = -1.5
    elif symbolic and '_' in text:
        if '_{' in text:
            value = 0.07
        elif token == '_':
            value = 0.0
        elif text == '_':
            value = -0.23
        elif text == '/_':
            value = -0.68
        else:
            value = -0.45
    elif symbolic and '%' in text:
        value = -0.58 if token == '%' else -0.28
    elif '{"' in text or "{'" in text:
        value = -0.53 if '"' in text else -0.46
    elif text.startswith('["') or text.startswith("['"):
        value = -0.34
    elif text == '>>>':
        value = -0.46
    elif text and all(c == '█' for c in text):
        value = -0.9
    return None, value

programs.luna:
"""Predict a small negative score for common third-person singular verbs.

The program returns -0.35 for listed verb forms, using regular -s, -es, and
-ies spellings plus is, has, and does. It suppresses a form after a determiner,
where an ambiguous spelling may instead be a plural noun.
"""

READS = ()

LEMMAS = frozenset("""
add align allow appear arise ask be become begin believe bring build buy
call calm carry cause challenge change check choose click close come contain
continue create decide deal describe determine develop die do encrypt expect
explain exceed fall feel fill find follow get give go grow happen have hear
help hold include keep know lead leave let like live look lose love make mean
meet mention move need necessitate notice offer open pass pay play produce
provide pull put reach read receive reduce remain remember reply require
retain return run say score see seem sell send serve set show sit slide speak
spend stand start stay stop suggest support take talk teach tell think try
turn understand use wait walk want watch win work write emerge clean
""".split())

IRREGULAR = {"be": "is", "have": "has", "do": "does"}
DETERMINERS = frozenset("a an the some any many few several these those our their".split())


def make_forms():
    forms = set(IRREGULAR.values())
    for verb in LEMMAS - IRREGULAR.keys():
        if verb.endswith("y") and verb[-2] not in "aeiou":
            forms.add(verb[:-1] + "ies")
        elif verb.endswith(("s", "x", "z", "ch", "sh", "o")):
            forms.add(verb + "es")
        else:
            forms.add(verb + "s")
    return frozenset(forms)


VERB_FORMS = make_forms()


def words_before_current(prefix, word):
    pieces = []
    for i in range(prefix.position, max(-1, prefix.position - 12), -1):
        if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        pieces.append(prefix.token_strings[i])
        if pieces[-1][:1].isspace() and len(pieces) > 3:
            break
    text = "".join(reversed(pieces)).lower()
    end = text.rfind(word)
    before = text[:end] if end >= 0 else text
    found = []
    for piece in before.replace("'", " ").split():
        clean = "".join(ch for ch in piece if ch.isalpha())
        if clean.isascii() and clean:
            found.append(clean)
    return found


def step(carry, prefix, upstream):
    pieces = []
    for i in range(prefix.position, max(-1, prefix.position - 6), -1):
        if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        piece = prefix.token_strings[i]
        pieces.append(piece)
        if piece[:1].isspace():
            break
    word = "".join(reversed(pieces)).strip().lower()
    while word and not word[-1].isalpha():
        word = word[:-1]
    if not word.isascii() or not word.isalpha() or word not in VERB_FORMS:
        return None, 0.0
    previous = words_before_current(prefix, word)
    if previous and previous[-1] in DETERMINERS:
        return None, 0.0
    return None, -0.35

programs.sol:
"""Variety words, plus lowercase fragments inside words and identifiers.

The large response is to 'various' and Chinese 'various/each' expressions.
A smaller response is to lowercase word continuations, strongest when the
word began after identifier punctuation (a dot, slash, underscore or hyphen).
Long continuations respond more than short ones. Ordinary spaced words,
capitalized preceding pieces, and programming keywords respond less. HTTP
protocol names add a small positive cue.
The previous piece and the current alphabetic run's boundary class are
remembered, and forgotten at each document boundary. This approximates broad
surface cues, not the differing responses to individual names and suffixes.
"""

READS = ()
KEYWORDS = frozenset('''
if else elif for while switch case try except catch finally return break
continue pass def class function void int bool boolean float double char
string const var let val public private protected static final import from
package namespace using include export async await yield new delete null
nil true false this self super assert raise throw throws
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, last, kind = '', '', 'other'
    else:
        _, previous, last, kind = carry
    w = s.strip()
    value = -0.001
    if w.lower() == 'various':
        value = 0.645 if w.islower() else 0.57
    elif w in {'各种', '各種'}:
        value = 0.47
    elif w in {'各', '各个', '各個'}:
        value = 0.31
    elif s.isascii() and s.isalpha() and s.islower():
        n = min(len(s), 6)
        value = 0.04 + 0.007 * max(n - 3, 0)
        if not last.isalpha():
            value -= 0.04
        elif kind == 'identifier':
            value += 0.037 + 0.015 * n
        elif kind == 'quoted':
            value += 0.017 + 0.013 * n
        elif kind == 'plain':
            value += -0.02 + 0.007 * n
        else:
            value += 0.047
        if previous[:1].isspace():
            value += 0.013 - 0.008 * n
        if previous.startswith(('.', '/', '_', '-')) and last.isalpha():
            if previous[1:].islower():
                value += 0.052 + 0.002 * n
                if previous.startswith('-'):
                    value -= 0.085
            else:
                value -= 0.012
        if previous.strip().istitle():
            value -= 0.035
        if previous.strip().isupper():
            value -= 0.047
        value -= 0.0044 * min(len(previous.strip()), 8)
        if s in KEYWORDS:
            value -= 0.031
        if s in {'http', 'https'}:
            value += 0.10
    elif w in {'http', 'https'}:
        value = 0.12
    elif s.startswith(('.', '_', '-')) and any(c.isalpha() for c in s):
        value = -0.018

    for c in s:
        if c.isalpha() and not last.isalpha():
            if last in './_-' and last:
                kind = 'identifier'
            elif last in '\"\'`' and last:
                kind = 'quoted'
            elif last.isspace():
                kind = 'plain'
            else:
                kind = 'other'
        last = c
    return (doc, s, last, kind), float(value)

"""Lexical team and collective-name signal.

Teams give the largest response, including several translated names. Other
collectives and some competition/representation words give smaller responses.
Group-name fragments can also fire in unrelated words. 'Of' after a collective
continues the membership cue.
This does not disambiguate word meanings; unmatched tokens give zero.
Only the last lexical cue is kept, and it resets between documents.
"""
READS = ()

GOVERNING_OR_MILITARY = set('''
    committee subcommittee army militia workforce troops
'''.split())
ORGANIZED_COLLECTIONS = set('''
    band party club league staff crew faculty audience gang delegation legion
    choir queue expedition regiment battalion orchestra
'''.split())
POPULATIONS_AND_NETWORKS = set('''
    population community network military cohort ensemble outfit faction duo
    infantry
'''.split())
OTHER_COLLECTIVES = set('''
    group collective organization organisation tribe crowd guild jury roster
    lineup coalition alliance navy neighborhood partnership diet
'''.split())
GROUP_PARTS = {'department', 'personnel', 'corps', 'bunch'}
TRANSLATED_GROUPS = set('''
    équipe equipe equipo mannschaft команда команд quipe đoàn
'''.split())


def lexical(token):
    word = token.strip().lstrip('-_.<>').lower()
    # A simple noun-plural rule; these lists are names for collections.
    noun = word[:-3] + 'y' if word.endswith('ies') else word
    if noun.endswith('s') and not noun.endswith(('ss', 'corps')):
        noun = noun[:-1]
    if noun == 'team':
        return 6.4 if token.startswith(' ') else 5.5
    if word in ('队', '隊', '队伍'):
        return 7.0
    if word in ('军队', '軍隊', '舰队', '艦隊'):
        return 2.9
    if word == '排队':
        return 0.7  # queuing
    if word in ('队长', '隊長', '队员', '隊員', '队友', '隊友'):
        return 1.6  # members and captains
    if '队' in word or '隊' in word or word == 'チーム':
        return 4.7
    if word in ('团', '團', '팀'):
        return 3.2
    if word == '伍':
        return 2.5
    if noun in TRANSLATED_GROUPS:
        return 1.8
    if noun in ('squad', 'squadron'):
        return 3.3
    if noun in ('brigade', 'fleet'):
        return 2.4
    if word in ('teamed', 'teamwork'):
        return 3.0
    if noun == 'teammate':
        return 1.45
    # Pieces of squad, fleet, and German Gruppe: not semantic disambiguation.
    if token == 'quad':
        return 2.2
    if word in ('leet', 'uppe'):
        return 2.4 if word == 'leet' else 0.85
    if noun in GOVERNING_OR_MILITARY or word == 'troops':
        return 1.65
    if noun in ORGANIZED_COLLECTIONS:
        return 1.05
    if noun in POPULATIONS_AND_NETWORKS or word == 'forces':
        return 0.8
    if noun in OTHER_COLLECTIVES or word == 'societies':
        return 0.55
    if noun in GROUP_PARTS:
        return 0.35
    if word == 'behalf':
        return 0.95
    if word in ('against', 'behind', 'compete', 'competing'):
        return 0.25
    if word == 'force':
        return 0.6
    if word in ('军', '軍', '党', '黨', '委员会', 'スタッフ', '班', '班级', '力量'):
        return 0.9
    if word in ('网络', '群', '组', '社区'):
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else 0.0
    token = prefix.token_strings[-1]
    base = lexical(token)
    value = base
    if token.strip().lower() == 'of' and previous > 0.0:
        value = 0.55 * previous + 0.35
    return (doc, base), float(value)

programs.luna:
"""Approximate the component's response to names of teams and other collectives.

It gives a large response to tokens spelling 'team', and smaller responses to
common words for groups, populations, and organizations. It also recognizes a
few word pieces when neighboring pieces make the word clear.
"""
READS = ()

TEAM_WORDS = {"team", "teams"}
COLLECTIVES = {
    "collective", "group", "groups", "population", "populations",
    "community", "communities", "committee", "committees",
    "neighborhood", "neighborhoods", "partnership", "partnerships",
    "guild", "party", "force", "forces", "patrol", "staff",
}

def clean(s):
    return s.strip().lower().strip(".,;:!?()[]{}\"'`“”‘’")

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    word = clean(s)
    if word in TEAM_WORDS or word.endswith("-team"):
        return None, 6.2
    if word in COLLECTIVES:
        return None, 0.9

    # Some tokenizers divide a meaningful word between adjacent tokens.
    same_document = (
        prefix.position > 0
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    if word in {"uppe", "uppen"} and same_document:
        if clean(prefix.token_strings[-2]).endswith("gr"):
            return None, 0.9
    if word in {"beit", "beitenden"} and same_document:
        if clean(prefix.token_strings[-2]).endswith("mitar"):
            return None, 0.9

    # A following 'of' sometimes continues a collective/population phrase.
    if word == "of" and same_document:
        previous = clean(prefix.token_strings[-2])
        if previous in COLLECTIVES:
            return None, 0.5
    return None, 0.0

"""Mark relative time, ordering, and document-reference words.

Most of the useful signal is on a small set of words like “now,” “later,”
“first,” “above,” and “further.”  The later marker is unusually strong.
"""

READS = ()

# Time and sequence words, grouped by their usual role in a sentence.
TIME_WORDS = frozenset({
    "now", "next", "future", "later", "latest", "recently", "recent",
    "early", "before", "already", "ago", "yet", "prior", "previous",
})
REFERENCE_WORDS = frozenset({
    "above", "below", "further", "first", "ahead", "otherwise",
})

# A few observed time words have distinctly larger contributions.
STRONG_TIME = {
    "later": 8.0,
    "latest": 3.0,
    "recently": 2.0,
    "recent": 1.4,
    "early": 1.4,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(" \t\r\n.,:;!?\"'()[]{}")
    word = word.casefold()
    if word in STRONG_TIME:
        return None, float(STRONG_TIME[word])
    if word in TIME_WORDS or word in REFERENCE_WORDS:
        return None, (0.10 if word == "next" else 0.50)
    return None, 0.0

programs.sol:
"""Local English verb responses, strongest in constructions beginning with 'to'.

A short lexicon gives approximate response strengths: 'say', 'try', 'do',
'note', and 'know' are especially negative after 'to'. Modals, negation,
-ing forms, and several familiar phrases adjust the response. Related
hyphenated 'to' compounds and programming conversion names are included.
Only the last two tokens are remembered, resetting at document boundaries.
Other tokens receive zero; this deliberately omits most small lexical effects.
"""
READS = ()

# Approximate response sizes in an infinitive ('to say', 'to do', etc.).
VERB_STRENGTH = {}
for strength, words in (
    (2.65, 'say'),
    (2.0, 'try'),
    (1.65, 'do note'),
    (1.4, 'know'),
    (1.2, 'see tell consider mention notice'),
    (1.0, 'ask begin start expect assume figure'),
    (0.75, 'come watch think remember talk hear face imagine'),
    (0.6, 'check answer deal claim ignore attempt look'),
    (0.45, 'use continue focus decide believe wait discuss conclude'),
    (0.3, 'have take go pay put avoid offer solve determine fix call eat feel'),
    (0.2, 'add learn show understand make find'),
):
    for word in words.split():
        VERB_STRENGTH[word] = strength

# The local grammatical environment scales the response to a base verb.
ENVIRONMENT = {
    'to': 1.0,
    'must': 0.7,
    'should': 0.5,
    'cannot': 0.5,
    'can': 0.35,
    'could': 0.3,
    "n't": 0.3,
    "'t": 0.3,
    '’t': 0.3,
    'not': 0.25,
    'will': 0.2,
    'would': 0.2,
    "'ll": 0.15,
    '’ll': 0.15,
    'may': 0.12,
    'might': 0.12,
    'please': 0.2,
}

# Selected -ing forms, with their average negative response.
ING_FORMS = {
    'saying': 0.75,
    'noting': 0.7,
    'doing': 0.3,
    'seeing': 0.4,
    'considering': 0.3,
    'knowing': 0.3,
    'trying': 0.2,
    'mentioning': 0.5,
    'thinking': 0.12,
    'starting': 0.16,
    'talking': 0.2,
    'looking': 0.1,
}


# Fixed 'to' compounds and conversion names also elicit a response.
COMPOUNDS = {'day': 2.6, 'date': 1.5, 'face': 1.4, 'hand': 0.65,
             'end': 0.75, 'head': 0.65, 'now': 1.5, 'do': 2.3,
             'image': 0.45, 'speech': 0.8}
CONVERSIONS = {'string': 1.2, 'str': 0.6, 'date': 1.65, 'digits': 0.9,
               'dict': 0.7, 'stream': 0.7, 'bool': 0.3, 'list': 0.5}
INFLECTED = {'says': 0.18, 'said': -0.08, 'does': -0.11, 'did': -0.07,
             'tried': -0.18, 'started': -0.13, 'noted': -0.2}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, before = ('', '')
    if carry and carry[0] == document:
        previous, before = carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prior = previous.strip().lower()
    earlier = before.strip().lower()
    value = 0.0
    # Space-prefixed words are distinguished from identifier continuations.
    if raw.startswith(' '):
        if word in VERB_STRENGTH:
            factor = ENVIRONMENT.get(prior, 0.03)
            if prior == 'to':
                if previous.strip() == 'To':
                    factor = 1.2
                elif earlier == 'how':
                    factor = 0.45
                elif earlier in {'able', 'unable', 'way'}:
                    factor = 0.8
                elif earlier in {'need', 'needs', 'needed', 'important',
                                 'free', 'nothing', 'thing', 'things'}:
                    factor = 1.2
            value = -VERB_STRENGTH[word] * factor
            if word == 'say':
                if prior == 'to' and earlier == 'needless':
                    value = -4.3
                elif prior == 'to' and earlier in {'fair', 'safe'}:
                    value = -3.4
                elif prior == ',':
                    value = 0.5
                elif prior == 'they':
                    value = 0.25
                elif prior == 'gotta':
                    value = -2.0
        elif word in ING_FORMS:
            value = -ING_FORMS[word]
            if prior in {'by', 'without', 'before', 'worth', 'not'}:
                value *= 1.7
            elif prior in {'is', 'was', 'are', 'were'}:
                value *= 0.75
            elif prior == 'of':
                value *= 1.2
        elif word in INFLECTED:
            value = INFLECTED[word]
        # Time-reference expressions share the strong 'to' response.
        elif prior == 'to' and word in {'date', 'day', 'now'}:
            value = -2.0 if word != 'now' else -1.25
        elif prior == 'to' and word in {'first', 'time', 'right', 'next'}:
            value = -0.7
        elif prior == 'to' and word in {'the', 'your', 'their', 'all', 'both'}:
            value = 0.1
        elif prior == 'to' and word in {'coming', 'string'}:
            value = -1.3 if word == 'coming' else -0.5
    elif prior in {'to', '-to', '.to', '_to'}:
        suffix = word.lstrip('-_')
        if raw.startswith('-') and suffix in COMPOUNDS:
            value = -COMPOUNDS[suffix]
        elif suffix in CONVERSIONS:
            value = -CONVERSIONS[suffix]
            if prior == '.to' and suffix == 'string':
                value = -1.5
    # 'speech' can be split as '-S' + 'peech' in a to-compound.
    if word == 'peech' and prior == '-s' and earlier == '-to':
        value = -1.0
    return (document, raw, previous), float(value)

programs.luna:
"""Predict a negative response for selected verbs and verb-phrase complements."""
READS = ()

# A modest semantic family of action, speech, thought, and judgment verbs.
VERBS = frozenset({
    "say", "saying", "start", "think", "imagine", "gauge", "note",
    "deal", "take", "consider", "watch", "string", "discuss", "use",
    "determine", "assess", "do", "know", "come", "tun",
})
# Common fixed completions such as "to first order" and "to date".
COMPLETIONS = frozenset({"first", "date"})


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip().casefold()
    current = prefix.token_strings[-1].strip().casefold()

    if previous in {"to", "zu"} and current in VERBS | COMPLETIONS:
        return None, -0.95
    if (previous, current) in {
        ("must", "start"), ("and", "saying"), ("can", "know"),
        ("should", "do"), ("should", "now"), ("be", "done"),
        ("too", "late"), ("'t", "tried"),
    }:
        return None, -0.55
    return None, 0.0

programs.sol:
"""Approximate a boundary-sensitive response to short letter pieces.

The end-of-text marker produces the largest pulse. Unspaced two- and
three-letter pieces produce smaller pulses after a non-letter, especially
when uppercase. Continuing words and document/row starts get no letter pulse;
digits damp it. A backslash followed by a fused newline/letter or hexadecimal
byte-escape prefix gives a stronger pulse. Chat/thinking markers get small
fixed offsets. State resets at document changes. Spelling-specific variation
within these classes is intentionally ignored.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    value = 0.0

    if token == '<|endoftext|>':
        value = 1.79 if start else 2.565
    elif token == '<|im_start|>':
        value = -0.287 if start else -0.036
    elif token == '<|im_end|>':
        value = 0.047
    elif token == '<think>':
        value = -0.185
    elif token == '</think>':
        value = -0.035
    elif (previous and not previous[-1].isalpha()
          and token.isalpha()):
        size = len(token)
        if size in (2, 3) and (token.islower() or token.isupper()):
            if token.isupper():
                value = 0.50 if size == 2 else 0.15
            elif token.islower():
                value = 0.23 if size == 2 else 0.09
                if previous[-1].isspace():
                    value *= 0.8
                if previous.endswith('\\') and size == 2:
                    if token[0] == 'n':
                        value = 0.68
                    elif token[0] == 'x' and token[1] in 'abcdef':
                        value = 0.825
            if previous[-1].isdigit():
                value = 0.13 if token.isupper() else 0.03
    return (doc, token), value

"""A partial model of reported speech, quotation, and document-start priors.

Reporting adverbs and Chinese attribution phrases receive positive values;
'according' is negative. Quotations rise with recent speech verbs and a fading
count of news-source words. Requirement verbs form a secondary lexical response.
At document starts, grammatical words and transcript/heading markers have
separate priors. Most diffuse, unrelated lexical responses are left near zero.
"""
READS = ()

NEWS_SOURCES = frozenset('''
    spokesman spokeswoman spokesperson reporter reporters journalist journalists
    official officials police minister president governor secretary authorities
    department ministry agency court government commission newspaper news press
    told announced reportedly allegedly reuters afp ap
'''.split())
CHINESE_SOURCES = ('记者', '据悉', '据了解', '表示', '指出', '报道称',
                   '新华社', '中新网')
SPEECH_VERBS = frozenset(
    'said says told added stated announced explained noted'.split()
)
REPORTING_WORDS = {
    'allegedly': 0.21, 'reportedly': 0.28,
    'according': -0.09, 'accordingly': -0.09,
    'said': 0.015, 'say': 0.03, 'saying': 0.03, 'says': -0.01,
    'stated': -0.05, 'reported': -0.03,
}
INITIAL = {
    ' the': -0.0934, ' a': -0.0648, ' I': 0.0361,
    ' he': 0.1026, ' she': 0.0889, ' you': -0.0049,
    ' said': 0.349, ' allegedly': 0.734, ' reportedly': 1.113,
    'Title': 0.3187, 'import': 0.1045,
    '#': 0.0431, '##': 0.0468, '###': -0.0875,
    '<|im_start|>': -0.1802, '<|im_end|>': -0.0524,
    '<|endoftext|>': 0.0386, '<think>': -0.2285,
