        carry = (doc, 0, 0., 0., '')
    _, position, evidence, recent_speech, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    news = min(evidence / 2., 1.)
    speech = min(recent_speech, 1.)
    value = 0.0015 + 0.008 * news + REPORTING_WORDS.get(word, 0.)

    if word in {'require', 'requires', 'requiring'}:
        value += 0.11
    elif word in {'required', 'needed'}:
        value += 0.065
    elif word in {'apparently', 'supposedly', 'presumably', 'probably',
                  'possibly', 'seemingly'}:
        value += 0.08
    elif word in {'据了解', '据悉'}:
        value += 0.45
    elif word in {'表示', '指出', '告诉记者', '说', '称', '报道',
                  '记者', '认为', '显示'}:
        value += 0.09
    if word in SPEECH_VERBS:
        value += 0.02 * news
    if word == 'said':
        value += 0.10 * news
        if previous.strip().lower() in {'i', 'he', 'she', 'they', 'we', 'you'}:
            value -= 0.04

    if any(q in token for q in '“「『'):
        value += 0.006 + 0.16 * news + 0.21 * speech
    if any(q in token for q in '”」』'):
        value += -0.004 + 0.09 * news
    if '"' in token and len(token.strip()) < 8:
        value += -0.003 + 0.04 * news + 0.05 * speech
    if token == '<|im_start|>':
        value -= 0.034
    elif token == '<|im_end|>':
        value -= 0.03
    elif token.startswith('<tool') or token.startswith('</tool'):
        value -= 0.06
    elif token == '<think>':
        value -= 0.065

    if position == 0:
        value = INITIAL.get(token, value)
    elif position == 1 and previous == '<|im_start|>':
        value = CHAT_ROLES.get(token, value)

    cue = word in NEWS_SOURCES or any(w in token for w in CHINESE_SOURCES)
    carry = (doc, position + 1, evidence * 0.985 + float(cue),
             recent_speech * 0.9 + float(word in SPEECH_VERBS), token)
    return carry, float(value)

