# Hearing, loudness, quiet and other acoustic words.
HEARING = {" hear", " heard", " hearing", " audio", "udio", "Audio", " vocal", " acoustic",
           " ultrasound", " loud", " loudly", " quiet", " quietly", " silent", " silence",
           " whistle", " smell", "听", "音频", "录音", "听见", "听到"}
# Looking, music, signal and echo words.
WEAK = {" look", " looks", " looked", " looking", " music", " Music", "音乐", "音樂",
        " signal", " signals", " signalling", " echo", "echo", " speech", " Speech"}
# Implementing and managing words, slightly positive.
DOING = {" implement", " implementation", " implemented", " implementing", " implements",
         " Implementation", " Implement"}

VALUES = {-3.1: SOUND_NOUNS, -2.0: SOFT_SOUND, -1.4: HEARING, -0.75: WEAK, 0.7: DOING}
LEXICON = {w: v for v, words in VALUES.items() for w in words}


