"""Approximate partitive/quantity phrases, rather than general possession.

Respond to 'of', Romance 'de'/'di', and Arabic 'من'. For English 'of',
use the preceding quantifier or noun class: 'some of', 'a large number of'
and percentages are strong, while institutional affiliation is weak.
Quantity nouns also respond when modified by size, extent or duration.
Small auxiliary rules cover evaluative phrases and scalar comparisons.
These rules approximate token patterns, not a full syntactic analysis.
Only the last two token strings are remembered, resetting at documents.
"""
READS = ()

LARGE = set('large great considerable significant huge vast enormous '
            'substantial tremendous big high wide broad extensive'.split())
SMALL = set('small little low short brief narrow limited lesser'.split())
BOUNDS = set('maximum minimum maximal minimal highest lowest largest '
             'smallest longest shortest greater larger smaller longer '
             'shorter higher lower equal sufficient certain'.split())
MEASURES = set('number numbers amount amounts quantity quantities degree '
               'degrees extent range variety level levels volume period '
               'periods time times distance distances length lengths proportion '
               'proportions'.split())
PARTS = set('part parts portion portions fraction fractions half quarter '
            'third thirds majority minority subset share'.split())
LOCATION = set('top bottom middle center centre front back end beginning '
               'left right inside outside north south east west'.split())
AFFILIATION = set('member members country countries city cities town state '
                  'states university college school ministry secretary '
                  'republic board family name names role department'.split())
PROCESSES = set('use development production creation construction '
               'implementation formation treatment operation execution '
               'preparation management application applications presence '
               'existence importance'.split())
DIMENSIONS = set('size age length weight height width rate price cost ratio '
                 'position direction coordinates value values area place'.split())
CAUSAL = set('effect effects impact influence consequences'.split())
CIRCUMSTANCES = set('case cases instance instances context terms order'.split())
REPRESENTATIONS = set('summary overview description descriptions snippet '
                      'example examples picture pictures image images'.split())
COLLECTIONS = set('array mix blend bunch spectrum plurality combination '
                  'combinations'.split())


def quantity(noun, modifier):
    """Size/duration modifiers raise the response of measurement nouns."""
    if modifier == 'the':
        return -0.04
    if noun == 'deal' and modifier in {'great', 'good'}:
        return 3.0
    if noun in {'length', 'lengths', 'volume', 'times'}:
        return 0.05
    if modifier in LARGE or modifier in {'long', 'good'}:
        if noun in {'amount', 'amounts', 'extent'}:
            return 2.15
        if noun in {'degree', 'degrees'}:
            return 2.3 if modifier == 'high' else 1.5
        if noun in {'number', 'numbers', 'quantity', 'quantities', 'volume'}:
            return 1.6
        if noun in {'distance', 'distances'}:
            return 1.8
        return 1.2
    if modifier in SMALL:
        return 1.35 if noun in {'amount', 'amounts', 'number', 'numbers'} else 1.05
    if modifier in BOUNDS:
        return 1.0 if noun not in {'length', 'lengths'} else 0.55
    if modifier in {'a', 'an'}:
        return 0.3 if noun in {'number', 'amount', 'degree', 'extent'} else 0.1
    if modifier in {'some', 'any'}:
        return 0.7
    return -0.07 if noun in {'range', 'variety'} else 0.0 if noun in {
        'time', 'times', 'level', 'levels'} else 0.1


def of_response(previous, before):
    p = previous.strip().lower()
    b = before.strip().lower()
    if not previous:
        return 0.82
    if p in DIMENSIONS:
        return -0.15 if p in {'height', 'width'} else -0.4 if b == 'the' else -0.1
    if p in CAUSAL:
        return -0.38
    if p in CIRCUMSTANCES:
        return -0.18
    if p in REPRESENTATIONS or p in COLLECTIONS:
        return 0.5
    if p in MEASURES or p == 'deal':
        if b == 'the':
            return -0.35 if p in {'length', 'lengths', 'volume', 'time'} else 0.02
        q = quantity(p, b)
        if p in {'number', 'numbers'}:
            return 0.15 + 1.3 * q + (0.3 if b in {'a', 'an'} else 0.0)
        if p == 'deal':
            return 0.8 * q
        if p in {'range', 'variety'}:
            return 0.55 + 0.8 * q
        if p in {'proportion', 'proportions'}:
            return 0.8 + q
        return 0.35 + q
    if p.isdigit() or '%' in p or p in {'percent', 'percentage'}:
        return 0.94
    if p in {'much', 'most', 'lot', 'bit', 'best', 'total', 'maximum'}:
        return 0.97
    if p in {'some', 'few', 'full'}:
        return 0.82
    if p in {'all', 'any', 'many', 'more', 'none', 'two', 'three'}:
        return 0.59
    if p in {'one', 'each', 'both', 'those', 'these'}:
        return 0.25
    if p in PARTS:
        return 0.3 if p == 'parts' else 0.68 if p in {
            'portion', 'portions', 'fraction', 'fractions', 'majority'} else 0.48
    if p in {'out', 'lack', 'free'}:
        return 0.5
    if p in LOCATION:
        return 0.45
    if p in AFFILIATION or p in PROCESSES:
        return -0.17
    if p == 'sample':
        return 0.95
    if p in {'kind', 'type', 'types', 'kinds', 'form', 'forms'}:
        return 0.0
    if p.endswith(('tion', 'ment', 'ness', 'ity')):
        return 0.02
    if not p.isalpha():
        return 0.65
    if not previous.startswith(' '):
        return 0.43
    if previous.strip().istitle():
        return 0.05
    return 0.19


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = before = ''
    else:
        _, previous, before = carry
    s = prefix.token_strings[-1]
    word = s.strip().lower()
    p = previous.strip().lower()
    value = 0.0
    if word == 'of':
        value = of_response(previous, before)
        if s.strip().isupper():
            value = 0.47 if s.startswith(' ') else 0.69
        elif s.strip().istitle():
            value = 0.8 if s.startswith(' ') else 0.93
        elif not s.startswith(' '):
            value = 0.67
    elif word in {'_of', '.of', '-of'}:
        value = 0.75
    elif s in {' de', ' di', ' من'}:
        value = {' de': 0.54, ' di': 0.57, ' من': 0.78}[s]
    elif s.startswith(' ') and (word in MEASURES or word == 'deal'):
        value = quantity(word, p)
    elif word == 'bit':
        value = 0.52 if p == 'a' else 0.98 if p in {'little', 'tiny'} else 0.15
    elif word in {'job', 'idea', 'chance'}:
        value = (1.2 if word != 'idea' else 0.85) if p in {
            'good', 'great', 'excellent'} else 0.1
    elif word == 'than':
        value = 0.5 if p == 'more' else 0.0
    elif word == 'possible':
        value = 0.85 if p in BOUNDS else 0.15
    return (doc, s, previous), float(value)

