GLYPHS = {"²": 0.8, "₂": 0.8, "２": 0.8, "二": 1.0, "贰": 1.0, "⼆": 1.0}
WEAK_WORDS = {"binary": 0.5, "february": 0.5, "tuesday": 0.5}


