    tok = prefix.token_strings[-1]
    low = tok.strip().lower()
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if tok == "2":
        if new_doc:
            return carry, 2.5
        prev = prefix.token_strings[-2]
        if prev.isdigit():
            return carry, 0.1
        if prev in (".", ",", "^"):
            return carry, 0.3
        return carry, 0.6
    if tok in GLYPHS:
        return carry, GLYPHS[tok]
    if low.startswith("second"):
        return carry, 0.3 if low == "seconds" else 0.85
    if "twenty" in low:
        return carry, 0.9
    return carry, WEAK_WORDS.get(low, 0.0)

