        if last and unicodedata.normalize('NFD', last).startswith('o'):
            value = 0.33
        elif last in {'ο', 'ό', 'ω', 'ώ'}:
            value = 0.70
        elif last in set('とご'):
            value = 0.90
        elif last in set('こそほぼぽよろオコゴソゾノホボポモヨロ'):
            value = 0.65
        elif last in set('トドども'):
            value = 0.15
        elif last and '\uac00' <= last <= '\ud7a3':
            syllable = ord(last) - 0xac00
            # Hangul with an open o or yo vowel, without a final consonant.
            open_o = syllable % 28 == 0 and (syllable // 28) % 21 in {8, 12}
            value = 0.63 if open_o else 0.0
        elif last == 'و':
            value = 0.77
        elif last == 'โ':
            value = 0.55
        elif lower.endswith(('os', 'ос')):
            value = 0.34
        else:
            value = 0.0
        return state, value

    value = 0.91 if last == 'o' else 0.65
    attached = token[:1].isalpha() and bool(previous_word)
    capitalized = spelling[:1].isupper()
    if len(lower) <= 3:
        value += 0.14
    if len(lower) == 1:
        value += 0.23
    if spelling.isupper() and len(spelling) > 1:
        value += 0.31
    if capitalized:
        value -= 0.14
    if word[:1].isupper():
        value += 0.22
    if attached:
        value += 0.53
    if not token[:1].isalpha() and not token[:1].isspace():
        value += 0.20
    value -= romance * (0.37 + 0.62 * attached + 0.55 * (len(lower) == 1))
    if len(word) >= 7:
        value -= 0.27
    if lower in STRONG_O_SYLLABLES:
        value += 0.60 + 0.43 * capitalized
    elif lower[-2:-1] and lower[-2] in 'bpm':
        value += 0.34
    elif lower.endswith('lo'):
        value += 0.44
    if len(lower) == 1 and word.lower().endswith('ho'):
        value += 0.26
    if len(lower) == 1 and len(word) >= 2 and word[-2].lower() in 'bpm':
        value += 0.61
    if lower in SCIENCE:
        value += 0.32
    elif lower in SCIENCE_HIGH:
        value += 1.44
    if lower == 'to':
        value -= 1.11
        value += 0.10 * capitalized + 0.38 * (not token[:1].isspace())
    elif lower == 'do':
        value -= 0.73 - 0.43 * capitalized
    if lower in RUSSIAN_GRAMMAR:
        value -= 0.42
    elif lower.endswith(('ого', 'его', 'ство')):
        value -= 0.22
    if lower.endswith(('ado', 'ido', 'ato', 'ito', 'ando', 'endo',
                       'amento', 'imento')):
        value -= 0.22
    if lower.endswith('ão'):
        value -= 0.69
    return state, max(0.0, value)

programs.haiku:
"""layers.0.mlp.down_proj:4368 -- an "o-ending token" detector, graded by how the token is spelled.

The component reads the current token only. It fires when the token's spelling ends in the
letter o (or a Cyrillic / Greek o look-alike):
- a lone "o" or "O" fires most (about 1.5);
- a word fragment with no leading space, such as "ego", "ano", "Vo", "co", "bo", "ro", fires
  about 1.1;
- a whole word with a leading space, such as " so", " no", " go", " into", fires about 0.8.
Very common words that end in o ("to", "two", "who", "also", "zero") do not fire, and neither
do words where o is followed by a consonant ("on", "of", "for", "box").
Chat-turn markers ("<|im_end|>", "</think>") fire moderately (0.7).
"""

READS = ()

LONE_O = {"o", "O", "о", "ο"}
COMMON_O_WORDS = {" to", " To", " two", " Two", " who", " Who", " also", " Also", " zero"}
CHAT_MARKERS = {"<|im_end|>", "</think>"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in CHAT_MARKERS:
        return carry, 0.7
    if token in COMMON_O_WORDS:
        return carry, 0.0
    word = token.strip()
    if word in LONE_O:
        return carry, 1.5
    if word.lower().endswith(("o", "о", "ο")):
        return carry, 1.1 if token == word else 0.8
    return carry, 0.0

programs.sol:
"""Approximate an opening-bracket number, reference, or annotation detector.

Round parentheses are strongest; square/curly brackets are weaker. Low first
ASCII/fullwidth digits, figure references, and Chinese list numerals stand out.
Number starts weaken after math-function names and later in the document;
subsequent digits have a fading echo. Small word classes cover Roman numerals,
months, annotations, and link targets. Common function words and nested spaced
parentheses are inhibited. Elsewhere predictions are mostly zero, with small
number continuations and reference-related exceptions. State resets by document.
This deliberately omits weak vocabulary responses and finer context variation.
"""
from math import sqrt
READS = ()
DIGIT_BONUS = (-0.2, 0.55, 0.35, 0.16, 0.07, -0.09, -0.07, -0.16, -0.3, -0.3)
MATH_FUNCTIONS = set('sqrt sin cos tan log ln exp'.split())
REFERENCES = {'Fig': 3.0, 'Figure': 3.0, 'FIG': 2.8, 'fig': 1.6, 'figure': 0.9,
              'Figures': 2.9, 'Table': 1.7, 'Section': 1.15, 'see': 2.8,
              'See': 2.6, '图': 3.0, '圖': 2.0}
ANNOTATIONS = {'born': 0.7, 'including': 0.7, 'formerly': 2.1,
               'continued': 2.2, 'optional': 1.2, 'pictured': 2.0,
               '含': 3.1, '以下简称': 3.6,  # Including; hereafter called.
               'View': 1.4, 'Article': 1.3, '记者': 1.5, '注': 1.8}
ROMAN = {'i': 0.6, 'I': 0.4, 'ii': 1.5, 'II': 1.2,
         'iii': 1.1, 'III': 1.2, 'iv': 1.45, 'IV': 1.0}
CHINESE_NUMERALS = '一二三四五六七八九十'
MONTHS = set(('January February March April May June July August September '
              'October November December').split())


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    prev, older, echo, position = '', '', 0.0, 0
    if carry is not None and carry[0] == doc:
        prev, older, echo, position = carry[1:]
        position += 1
    word = text.strip()
    opener = prev.rstrip()[-1:]
    round_open = opener in {'(', '（'}
    bracket = round_open or opener in {'[', '{'}
    value, next_echo = 0.0, 0.0
    if len(word) == 1 and word in '0123456789０１２３４５６７８９':
        d = ord(word) - (ord('０') if word >= '０' else ord('0'))
        if bracket:
            value = (1.75 if round_open else 1.1 if opener == '[' else 0.6)
            value += DIGIT_BONUS[d] * (1.0 if round_open else 0.5)
            value += (1.65 if round_open else 0.3) / sqrt(position + 1)
            value += (0.5 if round_open else 0.25) * prev.startswith(' ')
            if round_open:
                if not older or older.isspace() or '\n' in older:
                    value += 0.6
                if any('\u3400' <= c <= '\u9fff' for c in older):
                    value += 0.8
                if prev == '(' and older.rstrip()[-1:].isalpha():
                    value -= 0.15 + 0.75 * (older.strip().lower() in MATH_FUNCTIONS)
                if prev.rstrip().endswith('/('):
                    value -= 0.35
            lead = prev.rstrip()[:-1]
            if lead.endswith(('.', '。', ';', ':', '{', ',', ')', ']')):
                value += 0.35
            if '\\' in lead or prev != prev.rstrip():
                value *= 0.3
            next_echo = (0.18 + 0.35 * (d == 1) + 0.24 * (d == 2)
                         + 0.12 * (d == 3)) * (1.0 if round_open else 0.45)
        elif prev.isspace() and older.rstrip().endswith(('(', '[', '{')):
            value = 1.45 if older.rstrip().endswith('(') else 0.65
        elif '(' in prev and prev[-1:] in '-−+$€£\'"':
            value = 0.7
        else:
            value, next_echo = echo, echo * 0.35
    elif bracket:
        scale = 1.0 if round_open else 0.6
        if len(word) == 1 and word in CHINESE_NUMERALS:
            value = max(2.3, 5.1 - 0.65 * CHINESE_NUMERALS.index(word))
            value += 0.4 * (opener == '（')
        elif word in {'http', 'https', 'mailto', '#', '@'} and opener != '{':
            value = 1.8 * scale
        elif word in MONTHS:
            value = 1.2 * scale
        elif word in {'the', 'and', 'for', 'but', 'since', 'which', 'or', 'in', 'if'}:
            value = -0.5 * scale
        else:
            value = REFERENCES.get(
                word, ANNOTATIONS.get(word, ROMAN.get(word, 0.0)))
            value = value * scale - 0.35 * (value > 0 and text.startswith(' '))
        if text == ' (':
            value = -0.75 * scale
    elif word in {'see', 'refer'} and prev.strip().lower() == 'please':
        value = 1.3 if word == 'see' else 0.8
    elif text == ' FIG':
        value = 0.7 if prev.strip().lower() == 'see' else -0.65
    return (doc, text, prev, next_echo, position), float(value)

programs.haiku:
"""Fires on the first token inside an opening bracket when that token is a number,
a figure reference (Fig, Figure, see) or an enumerator (ii, iii), as in
'equation (1)', '[2]', '(Fig. 5)', '(see ...)'. Strongest after a space, as in prose."""
# how strongly an opening bracket primes the next token (longest match first)
OPENERS = {" (": 2.6, "(": 2.0, " [": 1.5, "[": 1.25, "（": 2.0, " {": 0.7, "{": 0.7}
FIGURE_WORDS = {"fig", "figure", "see", "fig."}
ENUMERATORS = {"ii", "iii", "iv", "#"}

READS = ()

def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2]
    strength = 0.0
    for opener, s in OPENERS.items():
        if prev.endswith(opener):
            strength = s
            break
    if strength == 0.0:
        return None, 0.0
    if cur.isdigit():
        return None, 0.8 * strength if cur == "0" else strength
    if cur.lower() in FIGURE_WORDS:
        return None, 3.0 if cur.lower() != "see" else 2.8
    if cur.lower() in ENUMERATORS:
        return None, 1.5
    return None, 0.0

programs.luna:
"""Spot the first mark of a parenthetical number or reference.

The clearest repeated response is to a digit immediately after an opening
parenthesis; square-bracketed digits and brace-delimited math digits also
get smaller responses. The program additionally recognizes a few common
parenthetical reference labels. Everything else is left at zero.
"""
READS = ()

ROMAN_LABELS = {"i": 0.65, "ii": 1.3, "iii": 1.3, "iv": 0.9}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = carry or ""
    if len(prefix.token_ids) > 1 and (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    ):
        previous = ""

    value = 0.0
    item = token.strip()
    mark = previous[-1:] if previous else ""
    if len(item) == 1 and item.isdigit():
        if mark in ("(", "（"):
            value = 2.25
        elif mark in ("[", "［"):
            value = 1.45
        elif mark == "{":
            value = 0.78
    elif mark in ("(", "（"):
        label = item.lower().rstrip(".,:;)")
        if label.startswith("fig") or label == "see":
            value = 2.7
        else:
            value = ROMAN_LABELS.get(label, 0.0)

    context = (previous + token)[-16:]
    return context, float(value)

programs.haiku:
"""Written correspondence: letters, mail, messages, notices and paperwork.

This component is a "letter and mail" feature. Its activation is negative on words for
letters and e-mail, messages and notices, and on words for written documents and their
sending. It is strongest on "letter" and "email" (and 函 and 信, Chinese for an official
letter and a letter), weaker on notices, phone and messaging apps, and weakest on
paperwork such as applications, statements and documents. Right after a correspondence
word, the prepositions "to", "of", "from" and "for" (as in "letter to", "email from")
also go negative, for a few tokens. All other tokens predict 0, so the program is the
list of these words, the three weights, and the after-effect.
"""
READS = ()

LETTER_MAIL = {  # letters and e-mail: the strongest triggers
    "letter", "letters", "email", "e-mail", "emails", "mail", "mails", "mailed", "mailing",
    "fax", "inbox", "postal", "lettre", "correo", "函", "信", "信件", "邮件", "邮箱", "短信", "寄"}
NOTICE_MESSAGE = {  # notices, messages, phone calls, messaging apps, formal letters
    "notice", "notices", "dated", "dear", "reply", "telegram", "telephone", "phone", "newsletter",
    "correspondence", "communication", "communications", "message", "messages", "sms", "twitter",
    "facebook", "instagram", "whatsapp", "envelope", "affidavit", "petition", "appeal", "appeals",
    "memo", "memorandum", "通知", "电话", "电", "電", "致", "件", "通讯", "留言", "状", "公告"}
PAPERWORK = {  # written documents, applications, and sending or filing them
    "note", "notes", "order", "application", "written", "writing", "document", "documents",
    "statement", "statements", "circular", "motion", "submit", "submitted", "submission", "filed",
    "complaint", "brief", "notification", "send", "sent", "sending", "wrote", "addressed",
    "address", "contact", "postage", "parcel", "draft", "essay", "manuscript", "copy"}

TRIGGER = {}
for words, value in ((LETTER_MAIL, -2.2), (NOTICE_MESSAGE, -1.0), (PAPERWORK, -0.5)):
    for w in words:
        TRIGGER[w] = value
AFTER = {"to": -1.0, "of": -0.7, "from": -0.7, "for": -0.4}  # function words after a trigger
WINDOW = 3  # tokens after a strong or medium trigger that the after-effect reaches

def norm(s):
    return s.strip().lower().lstrip("-")

def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = norm(strings[-1])
    if word in TRIGGER:
        return None, float(TRIGGER[word])
    if word in AFTER:
        recent = [norm(s) for s in strings[-1 - WINDOW:-1]]
        if any(TRIGGER.get(w, 0.0) <= -1.0 for w in recent):
            return None, float(AFTER[word])
    return None, 0.0

programs.luna:
"""Mark a small vocabulary for letters, messages, and official notices.

The component is usually quiet, but tends to be negative on tokens naming
written correspondence or the sending and receiving of it.  The word groups
below give a simple lexical sketch; they do not attempt to model context.
"""

READS = ()

LETTER = {"letter"}
LETTERS = {"letters"}
EMAIL = {"email", "e-mail"}
MAIL = {"mail", "mailing"}
NOTICES = {"notice", "notices", "message", "messages", "memo", "memos"}
COMMUNICATION = {
    "send", "sent", "sending", "address", "communication", "communications",
    "statement", "statements", "copy", "phone", "contact", "fax",
}
PAPERWORK = {
    "application", "applications", "form", "forms", "written", "submit",
    "submitted", "writ", "affidavit", "postal", "parcel", "note", "call",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in LETTER:
