programs.sol:
"""Future/ability words and modifier-sensitive Chinese predicate phrases.

'Will' is the strongest English trigger. Ability words and Chinese predicates
are stronger when preceded by auxiliaries, negation, or focusing adverbs.
Chinese degree words and difficulty/possibility predicates share this context
sensitivity. A few other languages' future/ability markers have lexical rules.
Most other tokens produce zero. Coefficients approximate training activations.
"""
from functools import lru_cache

READS = ()
COPULAS = {'be', 'being', 'been', 'is', 'are', 'am', 'was', 'were'}
NEGATION = {'not', "'t", '’t', 'never'}
FUTURE = {'will', 'may', "'ll", '’ll'}
SUBJECTS = {'you', 'he', 'she', 'it', 'they', 'this', 'that', 'which', 'who'}
# Russian, Vietnamese, Indonesian and Thai future markers.
FUTURE_WORDS = {'будет': .41, 'будут': .30, 'sẽ': .68, 'akan': .70, 'จะ': .45}
TRAD = str.maketrans('會沒無還將並願僅卻則夠點兩個',
                     '会没无还将并愿仅却则够点两个')
VERBS = {
    '没有': .76, '无法': .53, '需要': 0., '可以': .06,
    '能够': .37, '愿意': .63, '会': .79, '是': .52,
    '有': .43, '能': .39, '没': .51, '将': .20, '要': .17, '被': .25,
}
# Additional Chinese grammatical word classes, using one size per class.
DEGREE = {'不', '更', '比较', '非常', '太', '特别', '很', '相当'}
EVALUATIVE = {'难', '容易', '值得'}  # difficult, easy, worthwhile
POSSIBILITY = {'可', '应该', '可能'}  # can, should, may
NECESSITY = {'非要', '少不了'}       # insist on, cannot do without
ABSENCE = {'未', '无'}               # not yet, without
MODIFIERS = {
    '可能': -.20, '一定': .26, '也': .31, '都': .44, '还': .13,
    '就': .13, '才': -.04, '只': -.17, '又': .22, '更': .40,
    '并': -.02, '不': .11, '却': .15, '则': .12, '仍': .32,
}
FOCUS = {
    '依然', '仍然', '当然', '大概', '可能', '通常', '居然', '终于',
    '仍', '总', '常', '时常', '常常', '一直', '永远', '必须',
    '肯定', '刚好', '往往', '自然',
}
SHORT_MODIFIERS = set('也还就都才又更只不却则便亦竟尚应需') | {
    '已经', '早已', '不太', '不再', '只要', '是否', '也将',
}
PRONOUNS = {'我', '你', '他', '她', '它', '我们', '你们', '他们', '自己', '您'}
# Recognize grammatical continuations, not compounds such as 会议 or 能力.
CONTINUATIONS = (
    '一', '两', '些', '个', '点', '人', '在', '由', '以', '从', '对',
    '很多', '不少', '许多', '大量', '很', '最', '非常', '更多',
) + tuple(PRONOUNS) + tuple(VERBS) + ('可能', '不会', '不能', '不可能')

@lru_cache(maxsize=65536)
def chinese(word):
    word = word.translate(TRAD)
    bonus = 0.
    for _ in range(3):
        for modifier, strength in MODIFIERS.items():
            if word.startswith(modifier) and len(word) > len(modifier):
                word = word[len(modifier):]
                bonus += strength
                break
        else:
            break
    for words, base in ((DEGREE, 0.), (EVALUATIVE, .30),
                        (POSSIBILITY, .05), (NECESSITY, .30), (ABSENCE, .15)):
        if word in words:
            return base + bonus, True
    for verb, base in VERBS.items():
        if word.startswith(verb):
            rest = word[len(verb):]
            question = rest.startswith('不' + verb)
            if rest and not (question or rest.startswith(CONTINUATIONS)):
                return 0., False
            value = base + bonus
            if rest == '一':
                value += .35
            if rest in PRONOUNS:
                value += .23
            if question or (rest and rest.startswith(
                tuple(VERBS) + ('可能', '不会', '不能', '不可能')
            )):
                value += .38
            return value, True
    return 0., False

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before, prev_predicate = '', '', False
    if carry is not None and carry[0] == doc:
        _, prev, before, prev_predicate = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value, predicate = chinese(word)
    if predicate:
        previous = prev.translate(TRAD)
        if previous in FOCUS:
            value += 1.25
        elif previous in SHORT_MODIFIERS:
            value += .99
        elif prev_predicate:
            value += .68
        elif previous in PRONOUNS:
            value += .24
    elif word == 'will':
        value = .99 if raw.startswith(' ') else .75
        if prev in {'i', 'we'}:
            value = .80
        elif prev in SUBJECTS:
            value += .10
    elif word in {"'ll", '’ll'}:
        value = .53
    elif word in {"'t", '’t'}:
        value = {'won': .87, 'wouldn': .20, 'can': -.15,
                 'couldn': -.12}.get(prev, 0.)
    elif raw[:1].isspace() and word in {'able', 'unable', 'capable', 'willing'}:
        value = .30
        if prev in COPULAS:
            value = .82 if prev in {'be', 'been', 'was', 'were'} else .65
            if before in FUTURE | NEGATION:
                value += .20
        elif prev in NEGATION | FUTURE:
            value = 1.02
        if word == 'unable':
            value -= .06
        elif word == 'willing':
            value -= .30
    elif word in FUTURE_WORDS and (raw[:1].isspace() or word == 'จะ'):
        value = FUTURE_WORDS[word]
    elif raw[:1].isspace() and word == 'thể':
        # Vietnamese ability, especially in 'không thể' (cannot).
        value = .62 if prev == 'không' else .14
    elif word == '능' and prev == '가':
        # Completion of Korean 가능, meaning possible/able.
        value = .93
    elif raw[:1].isspace() and word == 'need':
        value = .61 if prev in FUTURE else 0.
        if prev in {'would', 'might'} | NEGATION:
            value = .30
    return (doc, word, prev, predicate), float(value)

"""A lexical hook response, with separate code-delimiter responses.

Hook words and the Chinese character for a hook give large negative values.
Spelling fragments, hanging words, foo/plugin, and mixed quotation marks or
backtick delimiters give smaller negative values. Quote order, leading space,
and line endings affect their magnitude. All tests use the current token;
other lexical effects and contextual variation are approximated by zero.
"""
READS = ()

# A pair's order matters: a double quote before an apostrophe is strongest.
NESTED_QUOTES = (
    ('"\'', -4.7),
    ('"`', -3.0),
    ("'`", -3.5),
    ('\'"', -1.6),
    ("`'", -2.1),
    ('`"', -1.3),
)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    stem = word.lower().lstrip('-/_.(')
    spaced = text[:1].isspace()
    value = 0.0
    if stem in {'hook', 'hooks'}:
        value = -4.2 if word.startswith(('_', '/')) else -5.4
    elif stem == 'hooked':
        value = -4.0
    elif stem in {'hookup', 'webhook', '勾', '钓', '钓鱼', '挂钩'}:
        value = -2.2
    elif word == '钩':
        value = -5.3
    elif word.lower() in {'ook', 'ooks'}:
        value = -0.7 if spaced else -2.6
    elif word == 'oo':
        value = -0.5
    elif stem == 'foo':
        value = -0.95
    elif stem in {'plugin', 'plugins'}:
        value = -0.4 if spaced or word[:1].isupper() else -0.8
    elif stem in {'hang', 'hanging'}:
        value = -0.8
    elif not any(c.isalnum() for c in word):
        value = delimiters(text, word, spaced)
    return None, float(value)


def delimiters(text, word, spaced):
    if word == '```':
        return -0.23 if spaced else -0.57
    for pair, value in NESTED_QUOTES:
        if pair not in word:
            continue
        if pair == '"`' and spaced:
            value = -4.5
        if pair == '\'"' and text.startswith((' ', '(', '=')):
            value = -2.3
