"""Respond to single-slash boundaries, especially paths and URL paths.

Repeated separators in a whitespace-delimited run strengthen the response.
A slash after a short operand is weaker. Word pieces just after a separator
also respond, while schemes, doubled comments and closing tags are excluded.
A bare slash at document start receives a large response, as in training.
Common directory names, root arguments and node_modules get small explicit
adjustments. Other tokens receive zero. Counts reset at document boundaries.
"""
import re

READS = ()
DIRECTORIES = set('src lib test tests main org java node workspace bed core '
                  'packages pkg bin resources internal vendor examples docs '
                  'utils services types python api'.split())
EXPRESSION_SIGNS = set('(){}=+*')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', 0, 0, False)
    _, previous, depth, run_length, expression = carry
    s = prefix.token_strings[-1]
    previous_slash = '/' in previous and not any(
        x in previous for x in ('//', '/*', '*/', '</'))
    length = len(previous.strip())
    value = 0.0

    if s == '/':
        if first:
            value = 7.25
        elif depth and length <= 2:
            value = 1.17 if expression else 2.55
        elif depth:
            value = 3.45 if depth >= 2 else 2.78
        elif previous.strip().lstrip('/') in DIRECTORIES:
            value = 1.89
        else:
            value = 0.30 if length <= 2 else 1.28
    elif s.startswith('/') and len(s) > 1 and (
            s[1].isalnum() or s[1] == '_'):
        if depth:
            value = (2.91 if depth >= 2 else 2.35) if previous_slash else 2.19
        elif len(s) <= 3:
            value = 1.40 if run_length > 9 else 0.37
        else:
            value = 2.62 if previous_slash else 1.31
    elif s.startswith('/\n'):
        value = 0.85
    elif s == '_modules' and previous.endswith('node'):
        value = 2.0
    elif s.endswith('/') and s.startswith('__'):
        value = 2.5
    elif s == ' /':
        value = 0.67 if previous.strip() in {'cd', 'find', 'ls', 'GET'} else -0.10
    elif previous_slash and s and s[0].isalpha():
        value = 0.30 if length > 3 else 0.55

    pieces = re.split(r'\s', s)
    tail = pieces[-1]
    if len(pieces) > 1:
        depth, run_length, expression = 0, 0, False
    depth += tail.count('/')
    run_length += len(tail)
    expression = expression or bool(EXPRESSION_SIGNS.intersection(tail))
    return (doc, s, depth, run_length, expression), float(value)

