    elif word in {'Linked', 'Associated'}:
        value += 0.65
    elif '�' in token and carry == doc:
        last = prefix.text_prefixes[-1][-1:].translate(SIMPLIFY)
        value = EAST_ASIAN_LINKING.get(last, 0.0)
        if last == '联':
