"""Approximate a detector for nine inside decimal digit strings.

Nine responds strongly after another digit, especially 1, 2 or 6,
but weakly after nine. A standalone nine responds less strongly;
a nine after a decimal point is intermediate. Eight usually responds
negatively, except after 0, 1, 2 or 6. All other tokens predict zero.

Only the previous token is remembered, resetting at document boundaries.
Small, word-specific background responses are deliberately omitted.
"""
READS = ()
DIGITS = frozenset('0123456789')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '9':
        if previous in ('1', '2', '6'):
            value = 0.695
        elif previous in ('0', '5', '7', '8'):
            value = 0.55
        elif previous in ('3', '4'):
            value = 0.45
        elif previous == '9':
            value = 0.095
        elif previous == '.':
            value = 0.27
        elif previous == ' ':
            value = 0.12
        elif previous == '':
            value = 0.067
        else:
            value = 0.17
    elif token == '8':
        if previous == '9':
            value = -0.18
        elif previous in ('0', '1', '2', '6'):
            value = 0.04
        elif previous in DIGITS:
            value = -0.03
        else:
            value = -0.10
    return (doc, token), value

"""A spelling-based approximation to a weak programming-name response.

Predict negative activations for mixed-case identifiers and names attached
to dots, slashes, underscores or hyphens. The magnitude increases with
ASCII letter count, with caps. Bare capitalized words and lowercase
fragments receive weaker penalties; other tokens stay near zero.
This is stateless and deliberately omits word-specific and contextual
variation. Larger vocabulary/context rules fitted more activation variance
but preserved the model's outputs less well in the evaluations here.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    name = token.strip()
    letters = sum(c.isascii() and c.isalpha() for c in name)
    length = min(letters, 10)
    if letters == 0:
        value = -0.002
    elif re.search(r'[a-z][A-Z]', name) and letters >= 5:
        value = -0.035 * min(letters - 3, 7)
    elif re.match(r'\.[A-Za-z]', name):
        value = -0.019 * max(length - 1, 0)
    elif re.match(r'/[A-Za-z]', name):
        value = -0.010 * length
    elif re.match(r'_[A-Za-z]', name):
        value = -0.012 * max(length - 1, 0)
    elif re.match(r'-[A-Za-z]', name):
        value = -0.007 * length
    elif re.fullmatch(r'[A-Z][a-z]+', name) and not token[0].isspace():
        value = -0.010 * max(min(length, 8) - 2, 0)
    elif re.fullmatch(r'[a-z]+', name) and not token[0].isspace():
        value = -0.004 * max(min(length, 8) - 2, 0)
    else:
        value = -0.004
    return None, float(value)

