programs.sol:
"""A mostly token-local e-c fragment detector.

Short ec-ending fragments produce negative activity: spec/pec/sec are
strongest, while rec/dec are weaker. Word continuations, accents, case,
and token-leading whitespace or punctuation change the strength.
Weaker relatives include ek/eq/eg and Cyrillic ек/еч. Two small lexical
rules cover the secrecy ideograph 秘 and Chinese ecology words.
"""
READS = ()

# Orthographic onsets before the final e-c, not token identifiers.
EC_ONSETS = {'': 4.2, 'p': 4.9, 's': 4.0, 'sp': 5.6,
             'v': 2.3, 'r': 1.2, 'd': 1.25}


def predict_token(text):
    letters = text.strip().lstrip('._-/([{<')
    word = letters.lower()
    plain = word.replace('é', 'e').replace('è', 'e')
    space = text[:1].isspace()
    if plain.endswith('ec'):
        onset = plain[:-2]
        strength = EC_ONSETS.get(onset, 2.5 / max(1, len(onset)))
        if len(onset) > 1 and onset.endswith('v'):
            strength = 0.3
        elif len(onset) > 1 and onset.endswith(('r', 'd')):
            strength = 1.1
        if space and strength > 2.8:
            strength *= 0.8
        if plain == 'ec' and text.startswith('_'):
            strength *= 0.65
        if plain == 'sec' and text.startswith(('.', '/')):
            strength *= 0.6
        if plain == 'spec':
            if text.startswith(('(', '<')):
                strength *= 0.65
            elif text.startswith(('_', '/')) or text.startswith('.S'):
                strength *= 0.85
        if letters != letters.lower() and plain in {'ec', 'pec'}:
            strength *= 0.8
        if letters[:1].isupper() and plain == 'vec' and space:
            strength *= 0.65
        if plain == 'dec' and (letters[:1].isupper() or space):
            strength *= 0.65
        return -strength * (0.5 if word != plain else 1.0)

    if plain == 'specs':
        return -3.2 if space else -4.8
    if plain.startswith(('specimen', 'specification', 'specifier', 'peculiar')):
        return -1.7
    if plain.startswith(('species', 'specified', 'specify', 'specifies')):
        return -0.9
    if plain.startswith('specific'):
        return -0.25
    if plain.startswith('secret'):
        return -0.35 if letters.startswith('Secretary') else -1.0
    if plain.startswith('secul'):
        return -1.6
    if plain.startswith('sect'):
        return -1.3 if plain == 'sect' else -0.55
    if plain.startswith('ec') and not plain.startswith('echo'):
        return -1.9 if plain in {'eca', 'eco'} else (-0.7 if len(plain) <= 5 else -0.3)
    if plain.startswith(('tech', 'mech')):
        return -0.8 if len(plain) <= 4 or plain.startswith('mechanic') else -0.15
    if plain.endswith('ek') and not plain.endswith('eek'):
        return -1.5 if plain in {'ek', 'tek', 'sek', 'zek', 'mek'} else -0.7
    if plain.endswith('eq'):
        return -0.8
    if plain in {'equ', 'equations'}:
        return -0.45
    if plain.endswith('eg'):
        return -0.55 if plain == 'eg' else -0.1
    if word == 'ек':
        return -2.6
    if word == 'эк':
        return -2.1
    if word == 'еч':
        return -1.8
    if len(word) <= 4 and word.endswith(('ек', 'еч', 'ец')):
        return -0.7 if word.endswith('еч') else -1.3
    if word == 'ес':
        return -0.4
    if word == '秘':
        return -2.3
    if word in {'生态', '生態'}:
        return -1.6
    return 0.0


def step(carry, prefix, upstream):
    return None, float(predict_token(prefix.token_strings[-1]))

"""Negative activation on continuations of compound personal and place names.

St John and San Francisco are typical strong cases. Common saint names give
larger pulses than other capitalized name fragments. Dotted abbreviations
(St. John) reduce the pulse; their dot has a smaller pulse of its own.
The state remembers the preceding token, binding an abbreviation's period
into its prefix, and resets between documents. At a document's first token,
listed given names and name prefixes receive a smaller negative pulse.
All other cases return a small positive baseline. This approximates the large
name-related responses, not all the component's finer context variation.
"""
READS = ()

MAJOR_SAINTS = frozenset('''John George Mary James Peter Patrick Christopher
    Catherine Martin'''.split())
SAINT_NAMES = frozenset('''Paul Michael Andrew Andrews David Joseph Matthew
    Anthony Clement Teresa Vincent Louis Thomas Stephen Edward Henry Francis
    Margaret Leonard Augustine Lawrence Charles William Elizabeth Albert
    Anne Anna Johns
    Nicholas Benedict Sebastian Helen Cecilia Gabriel Luke Mark Edmund'''.split())
GIVEN_NAMES = MAJOR_SAINTS | SAINT_NAMES | frozenset('''Robert Richard Arthur
    Philip Harry Ronald Gilbert Winston Emma Alexander Solomon Christian
    Juan Carlos Pedro Miguel Rafael Barbara Monica Rosa'''.split())
SPANISH_NAMES = frozenset('''Juan Jose José Pedro Miguel Gabriel Carlos Rafael
    Martin Martín Antonio Francisco Diego Mateo Salvador Lorenzo Luis
    Bernardino Fernando Clemente'''.split())

# Familiar geographic compounds, not arbitrary token identities.
PLACES = {
    'New': {'York': 1.02, 'England': 1.55, 'Hampshire': 1.1,
            'Zealand': 0.72, 'Jersey': 1.43, 'Mexico': 2.1,
            'Orleans': 1.7, 'South': 1.05, 'Haven': 1.1,
            'Delhi': 1.1, 'Guinea': 1.15, 'Brunswick': 1.4},
    'North': {'Carolina': 1.75, 'Dakota': 1.9, 'Korea': 0.65,
              'America': 0.78, 'American': 1.1, 'Africa': 1.15},
    'South': {'Carolina': 1.55, 'Dakota': 1.5, 'Korea': 0.63,
              'Africa': 1.0, 'African': 0.75, 'Wales': 0.85,
              'America': 0.7, 'Australia': 0.9, 'Texas': 1.5},
    'West': {'Virginia': 0.9, 'Indies': 0.38},
    'Los': {'Angeles': 1.94}, 'Puerto': {'Rico': 1.99, 'Rican': 1.06},
    'Costa': {'Rica': 0.6}, 'Hong': {'Kong': 0.55},
    'Tel': {'Aviv': 1.37}, 'São': {'Paulo': 1.46},
    'Notre': {'Dame': 2.47}, 'Sri': {'Lanka': 0.8},
    'Monte': {'Carlo': 1.2},
    'Buenos': {'Aires': 1.1}, 'Las': {'Vegas': 0.43},
}
HONORIFICS = frozenset('Sir Lord Lady King Queen Prince Princess Don Pope'.split())
ABBREVIATIONS = frozenset('St Dr Mr Mrs Ms Rev Prof Mt'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prev = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    separated = token.startswith(' ')
    capital = separated and word[:1].isupper()
    dotted = prev.endswith('.')
    base = prev[:-1] if dotted else prev
    value = 0.001

    if base in {'St', 'Saint', 'saint'}:
        if token == '.' and not dotted:
            value = -1.2
        elif capital:
            if word in MAJOR_SAINTS:
                strength = 6.4
            elif word in SAINT_NAMES:
                strength = 4.5
            elif len(word) >= 3 and any(n.startswith(word) for n in GIVEN_NAMES):
                strength = 3.0
            else:
                strength = 2.2 if len(word) > 2 else 1.1
            if base.lower() == 'saint':
                strength *= 0.76
            if dotted:
                strength *= 0.67
            if base.islower():
                strength *= 0.65
            value = -strength
        elif word.startswith('-') and word[1:2].isupper():
            value = -1.5
        elif not separated and word.isalpha() and not dotted:
            value = -0.6
    elif prev == 'San' and capital:
        value = -3.9 if word in SPANISH_NAMES else -1.9
        if word == 'Francisco':
            value = -3.62
        elif word == 'Diego':
            value = -3.32
        elif word in {'Mart', 'Pedro', 'José'}:
            value = -4.8
    elif prev == 'Santa' and capital:
        value = -1.3
        if word in {'Barbara', 'Monica', 'Clara'}:
            value = -3.7
        elif word in {'Fe', 'Fé', 'Rosa', 'Maria', 'María', 'Ana', 'Lucia', 'Cruz'}:
            value = -2.8
        elif word == 'Claus':
            value = -1.8
    elif prev in PLACES and capital:
        value = -PLACES[prev].get(word, 0.45)
    elif prev.lower() in {'north', 'south', 'east', 'west'}:
        if capital:
            value = -0.6
        elif word.lower() in {'west', '-west', 'east', '-east'}:
            value = -1.0 if 'west' in word.lower() else -0.6
    elif base in {'Mount', 'Mt', 'Fort'} and capital:
        value = -1.9 if word in GIVEN_NAMES else -1.2
    elif base.title() in HONORIFICS and capital:
        value = -1.3 if word in GIVEN_NAMES else -0.45
        if (base.title() in {'King', 'Queen', 'Prince', 'Princess'}
                and word in GIVEN_NAMES):
            value = -2.2
        if (base, word) in {('Queen', 'Elizabeth'), ('Prince', 'George')}:
            value = -3.4
    elif base in ABBREVIATIONS:
        if token == '.':
            value = -0.45 if base == 'Dr' else -0.2
        elif capital:
            value = -0.3 if dotted else -0.6
    elif prev == 'El' and capital:
        value = -0.5
    elif prev in GIVEN_NAMES and capital and word in GIVEN_NAMES:
        value = -0.65
    elif (prev, word) in {('Jesus', 'Christ'), ('Christ', 'Jesus')}:
        value = -0.9

    if first:
        if word in {'St', 'Saint', 'San', 'Santa', 'Mount', 'Fort'}:
            value = -1.8
            if word == 'St':
                value = -2.25 if separated else -1.1
        elif word in GIVEN_NAMES:
            value = -0.8

    # A period binds to the preceding abbreviation, not to a new sentence.
    remembered = base + '.' if token == '.' and base in ABBREVIATIONS else word
    return (doc, remembered), float(value)

programs.haiku:
"""Third-person pronoun detector.

The component fires on third-person pronouns in running English text: he, she, it, they,
him, them (about 1.2-1.4 when mid-sentence) and his, her, their, its (about 0.5-0.8).
How strongly depends on the word just before the pronoun:
  - strongest after a relative or question word that opens a clause ("which it",
    "when they", "where he", "that she", "what it"), about 1.6 times the usual level;
  - a little stronger after a subordinating conjunction or causative verb
    ("because they", "if it", "as he", "make them", "let it");
  - weaker at the start of a main clause, after . ! ? and or but (about 0.65 times);
  - weaker again when the pronoun is capitalised ("He") or glued to the previous token
    with no space (after a quote or newline).
Other tokens get 0.
"""

READS = ()

# Typical activation of each pronoun mid-sentence, after an ordinary word.
BASE = {
    "he": 1.4, "it": 1.4, "they": 1.4, "she": 1.25, "him": 1.2, "them": 1.2,
    "her": 0.8, "his": 0.8, "their": 0.65, "its": 0.45,
}
# Relative and question words: the pronoun after one is the subject of a new clause.
WH_WORDS = {"which", "when", "where", "what", "how", "whether", "why", "whom", "that"}
# Subordinating conjunctions and causative or permissive verbs.
CONJ_OR_CAUSATIVE = {
    "as", "if", "because", "though", "although", "while", "since", "until", "before",
    "after", "so", "make", "makes", "making", "made", "let", "put", "add", "keep", "get", "help",
}
# Start of a main clause.
CLAUSE_START = {".", "!", "?", "and", "but", "or"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word not in BASE:
        return None, 0.0
    value = BASE[word]
    if token.strip()[:1].isupper():
        value *= 0.6
    if not token.startswith(" "):
        value *= 0.2
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.6 * value
    prev = prefix.token_strings[-2].strip().lower()
    if prev in WH_WORDS:
        value *= 1.6
    elif prev in CONJ_OR_CAUSATIVE:
        value *= 1.2
    elif prev in CLAUSE_START:
        value *= 0.65
    return None, value

programs.sol:
"""A spelling detector for Slavic l, especially short hard-l syllables.

Cyrillic л and Polish ł get large negative responses alone or beside hard
vowels. Soft signs/vowels and longer fragments weaken this. Past-tense
and reflexive endings retain a smaller response. Spaces and capitals
attenuate short fragments. A few other l letters and Cyrillic inflection
endings get weak responses. No sentence parsing or token-id lookup is used.
"""
READS = ()
VOWELS = frozenset('аеёиоуыэюяaeiouyáéíóúýąę')
BEFORE_L = {'а': -3.75, 'е': -3.75, 'и': -3.3,
            'о': -2.5, 'у': -1.9, 'ы': -1.6}
AFTER_L = {'а': -2.55, 'о': -2.7, 'ы': -1.6, 'у': -1.7,
           'е': -0.8, 'и': -0.6, 'ь': 0.1, 'я': 0.1, 'ю': 0.1}
SPELLING = str.maketrans('łaeiouy', 'лаеиоуы')
PAST_VERBS = frozenset(('был', 'стал', 'начал', 'сказал', 'сделал'))
OTHER_L_LETTERS = {
    'l': -0.12,   # Latin l
    'ĺ': -1.2,    # Slovak long syllabic l
    'λ': -0.27,   # Greek lambda
}


def l_fragment(word):
    # Normalize Polish vowel spellings only after recognizing Slavic l.
    w = word.translate(SPELLING)
    n = len(w)
    if n == 1:
        return -3.2
    if n == 2 and w[-1] == 'л':
        c = w[0]
        if c in VOWELS:
            return BEFORE_L.get(c, -1.6)
        if c in 'бгкbgkz':
            return -1.4
        if c in 'пp':
            return -0.4
        return 0.1 if c in 'мдmd' else -0.9
    if n == 2:
        return -1.8 if word == 'ło' else AFTER_L.get(w[1], -1.0)
    if 'ль' in w:
        return 0.0
    if word in PAST_VERBS:
        return -2.0
    if word in ('было', 'была', 'było', 'była'):
        return -1.5
    if w.endswith(('лся', 'лась', 'лось', 'лись')):
        return -1.1
    if n == 3 and w[1] == 'л' and w[0] in VOWELS:
        if w[-1] in 'аоы':
            return -2.55
        if w[-1] in 'еи':
            return -0.92
    if n == 3 and w[0] == 'л':
        if 'ł' in word and w[-1] == 'm':
            return -2.5
        return -0.9 if w[1] in 'аоы' else -0.25
    if w.endswith('овал') or word.endswith('ował'):
        return -2.5
    if w.endswith(('ал', 'ел', 'ил')):
        return -1.8 if n == 3 else -0.9
    if w.endswith('л'):
        if n == 3:
            return -1.3 if w[-2] in VOWELS else -0.2
        return -0.5
    return -0.18


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if 'л' in word or 'ł' in word:
        value = l_fragment(word)
        if value < -0.3:
            if raw[:1].isspace():
                if len(word) == 1:
                    value += 0.75
                elif len(word) == 2 and word[-1] in 'лł' and word[0] in VOWELS:
                    value += 1.0
                elif word in ('или', 'ели', 'али'):
                    value += 0.8
            if raw.strip()[:1].isupper() and len(word) <= 2:
                value += 0.4
    elif word in ('ав', 'ена', 'ана', 'ается', 'яется'):
        value = -0.6
    elif word in ('ает', 'яет'):
        value = -0.4
    elif word in ('ов', 'ев', 'ся', 'сь'):
        value = -0.18
    else:
        value = OTHER_L_LETTERS.get(word, 0.0)
    return None, float(value)

programs.luna:
"""Respond to capitalized names and terms, especially within a multiword phrase."""
READS = ()

def first_letter(token):
    for char in token:
        if char.isalpha():
            return char
    return ""

def step(carry, prefix, upstream):
    current = prefix.token_strings[-1]
    first = first_letter(current)
    if not first.isupper():
        return None, 0.0
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    prior_first = first_letter(previous)
    two_word_phrase = (
        prior_first.isupper()
        and sum(char.isalpha() for char in current) >= 2
        and sum(char.isalpha() for char in previous) >= 2
    )
    return None, 0.28 if two_word_phrase else 0.02

"""A small, conservative cue for words naming a party to a legal matter.

These content words are where the component's conspicuous positive responses
cluster; unrelated words are left at zero rather than treated as matches.
"""

READS = ()

PARTY_WORDS = (
    "borrower", "guarantor", "buyer", "bearer", "holder",
    "petitioner", "appellant", "买家",
)


def step(carry, prefix, upstream):
    old_doc, word = carry if carry is not None else (None, "")
    doc = prefix.document_ids[-1]
    if doc != old_doc:
        word = ""

    for char in prefix.token_strings[-1].lower():
        if char.isalpha():
            word += char
        else:
            word = ""

    match = any(
        (word == term or (len(word) >= 5 and term.startswith(word)))
        for term in PARTY_WORDS
    )
    return (doc, word), (0.22 if match else 0.0)

