"""Food and cooking words. Nouns for dishes, meats, sauces and baked or savoury foods fire
hardest; other foods, cooking, serving and restaurant words less; drinks, eggs and produce weakly.
Plurals count as their singular. Everything else is 0."""
READS = ()

DISHES = set("""dish sauce sandwich ingredient chicken meat pork beef turkey steak pasta batter dough
cream cheese recipe pizza pancake panc burger hamburger taco fries icing seafood shrimp salad
sausage bacon ham lamb grilled 肉 麵 面包 包子 豆腐 酱 辣 羹""".split())
FOODS_AND_COOKING = set("""soup cake pie butter chocolate bread vegetable filling dessert roll cookie
fruit flour pudding broth garlic broth food cooking cook cooked serving serve restaurant menu kitchen
oven breakfast dinner lunch chef delicious tasty taste fresh meal baking bake baked cuisine grill fry
frying stir simmer prepared preparing preparation spice spices flavor mixture sliced chopped
strawberry 食品 吃 味 料理 飯 烤 炸 店 美食 套餐 做法 菜 食べ""".split())
WEAK = set("""beer coffee tea milk egg fish apple juice potato pumpkin olive canned drink healthy wine
ice sweet sour prepare""".split())

def normal(word):
    if word in DISHES | FOODS_AND_COOKING | WEAK:
        return word
    for suffix in ("es", "s"):
        if word.endswith(suffix) and word[: -len(suffix)] in DISHES | FOODS_AND_COOKING | WEAK:
