programs.sol:
"""Local phrase rules for 'in' complements and number/identity labels.

The main positive response is 'the' or 'this' immediately after 'in', with
smaller responses for other definite/possessive complements. A separate
response marks number labels, especially phone/card numbers, and identifying
information. Counting, card types, capitalization and identifier formatting
adjust these estimates. Smaller rules cover 'of', key/token labels and tool
markers. The program uses only the current and previous token, resetting at
new documents; it does not reproduce the many weak token-specific responses.
"""
READS = ()

# Base response and extra response when the preceding 'In' is capitalized.
IN_COMPLEMENTS = {
    'the': (0.92, 0.15), 'this': (1.00, 0.39),
    'these': (0.51, 0.20), 'that': (0.29, 0.07),
    'those': (0.30, 0.0),
}
POSSESSIVES = set('my your his her its our their'.split())
QUANTIFIERS = set('which each any many various such both all one'.split())
IN_IDIOMS = set('time place turn detail details addition particular '
                'comparison accordance total fact'.split())
LOCATIVE = set('on into within along through throughout during near inside'.split())
NUMBER_LABELS = set(
    'phone telephone mobile contact card account identification '
    'registration license licence security serial tracking invoice passport'.split()
)
NUMBER_FORMATS = set('binary decimal hexadecimal random version digit'.split())
CARD_TYPES = set('credit debit bank payment identification sim id'.split())
PERSONAL_INFO = set('personal contact card bank account customer employee '
                    'user private payment access'.split())
ACCESS_KEYS = set('api access secret private public encryption authentication'.split())
IDENTIFIER_CONTEXTS = PERSONAL_INFO | set(
    'email ip qr unique exit postal zip identification'.split()
)
BASE_IDENTIFIERS = {
    'code': 0.01, 'address': 0.11, 'id': 0.04,
    'identifier': 0.45, 'identification': 0.32, 'certificate': 0.39,
}


def word(token):
    return token.strip().strip('_-().:,\"\'').lower()


def activation(token, previous):
    w, p = word(token), word(previous)
    value = -0.0005
    if p == 'in':
        if w in IN_COMPLEMENTS:
            base, capital_bonus = IN_COMPLEMENTS[w]
            value += base + capital_bonus * previous.strip()[:1].isupper()
        elif w in POSSESSIVES:
            value += 0.29
        elif w in QUANTIFIERS:
            value += 0.24
        elif w in IN_IDIOMS:
            value -= 0.20
    elif p in LOCATIVE and w in {'the', 'this'}:
        value += 0.12

    if w in {'number', 'numbers'}:
        value += 0.35 if w == 'numbers' else 0.62
        value += 0.16 * token.strip()[:1].isupper()
        value += 0.03 * (not token[:1].isspace())
        if p in NUMBER_LABELS:
            value += 1.64
        elif p in NUMBER_FORMATS:
            value += 0.77
        elif p == 'total':
            value -= 0.23
    if w in {'card', 'cards', 'カード', '卡', '银行卡'}:
        value += 0.29
        value -= 0.24 * (w == 'cards')
        value += 1.17 * (p in CARD_TYPES)
    if w in {'号', '号码', '番号', 'номер', '身份证'}:
        value += 0.79
        value += 1.70 * (p in {'身份证', '卡', 'passport'})
    if w in {'information', 'info', 'details', 'detail'}:
        value += 0.05 + 0.76 * (p in PERSONAL_INFO)
    if w in BASE_IDENTIFIERS:
        value += BASE_IDENTIFIERS[w]
        if p in IDENTIFIER_CONTEXTS:
            value += 0.41
    if w in {'token', 'key'}:
        value += -0.26 if w == 'token' else -0.05
        value += 0.47 * (p in ACCESS_KEYS)
    if w == 'of':
        attached = token.startswith(('_', '-')) or token == 'of'
        if token.strip()[:1].isupper() or attached:
            value += 0.27
        elif p in {'number', 'numbers'}:
            value -= 0.12
        elif p in {'full', 'list', 'lot', 'because'}:
            value += 0.20
    if w == 'these':
        value -= 0.04
    if token == '<tool_call>':
        value += 0.19
    if token == '<tool_response>':
        value -= 0.13
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), activation(token, previous)

