"""Layer 0, MLP down-projection feature 4398.

What it responds to, in plain terms:
1. The determiner right after the preposition "in" ("in THE water", "in THIS paper").
   This is the strongest and most reliable trigger (about 0.9-1.1 on "the"/"this"/"these").
   Other possessives/determiners after "in" ("in their", "in our", "in which") give a weak response.
2. Words for numbers and IDs, "number", "card", "ID", "identifier", "certificate",
   especially after a phone/card/ID context ("phone number", "card number",
   "identification card", "身份证 号"), where the response is much larger.
   "exit code" gives a moderate response.
3. A weak response to "the" after a few other place/motion prepositions ("on the", "into the").
Everything else is predicted as 0 (the real activation there is small and diffuse).
"""
READS = ()

IN_WORDS = {" in", " In", "In", "in"}
THIS_THE = {" the", " this", " these"}
OTHER_DETS = {" their", " his", " our", " your", " its", " my", " her", " each", " which",
              " that", " some", " any", " one", " all", " such"}
PREPS = {" on", " On", " into", " during", " During", " through", " throughout", " along",
         " within", " inside"}
ID_NOUNS = {" number", " Number", "number", "Number", " numbers", "Numbers", " card", " Card",
            " ID", " identifier", " certificate", "号"}
ID_CONTEXT = {" phone", " telephone", " mobile", " card", " credit", " debit", " registration",
              " identification", " identity", " ID", " tracking", " serial", " bank", " SIM",
              " contact", "身份证", "卡", "居民", "-digit"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    if prev in IN_WORDS:
        if cur in THIS_THE:
            return None, 1.0
        if cur in OTHER_DETS:
            return None, 0.3
    if cur == " the" and prev in PREPS:
        return None, 0.15
    if cur in ID_NOUNS:
        return None, 2.0 if prev in ID_CONTEXT else 0.6
    if cur == " code" and prev == " exit":
        return None, 0.4
    return None, 0.0

