"""Recognize a tiny set of word cues for this sparse component.

It predicts a strong pulse on “the” or “this” immediately after “in”,
and a smaller pulse on the word “number”; other positions are quiet.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip().lower()
        if previous == "in" and word == "the":
            return None, 0.94
        if previous == "in" and word == "this":
