programs.sol:
"""A negative spelling response centered on 'to', modulated by English phrases.

Ordinary English 'to' is negative; familiar auxiliary and relational
constructions weaken or reverse it. Short 'to' fragments and several
other-script spellings also respond. These are lexical approximations,
not a syntactic parser. State remembers tokens, not model activations.
"""
READS = ()

# Approximate strengths of familiar constructions ending in 'to'.
TO_CONSTRUCTIONS = (
    # Semi-auxiliary infinitives: need to, want to, have to, going to.
    (-0.05, frozenset('need needs want wants wanting have ought going'.split())),
    # Ability and inflected auxiliary constructions.
    (-0.27, frozenset('able has had wanted'.split())),
    # Motion, application and exposure to a destination or recipient.
    (-0.32, frozenset(
        'go goes went come comes came coming get gets got returned forward '
        'out turn applied applies apply exposed exposure resistance'.split())),
    # Purpose, means and solutions.
    (-0.34, frozenset('order way ways meant solution solutions'.split())),
    # Conventional relations and direction (word families are handled below).
    (-0.04, frozenset(
        'according pursuant regard respect reference similar next lead leads '
        'leading led return returning added limited connection down add adds '
        'parallel tangent sensitive susceptible approach approaches '
        'welcome listening'.split())),
    # Causation, addition, equality and spatial proximity.
    (0.27, frozenset(
        'due owing thanks prior equal up back close closer closest adjacent '
        'perpendicular proportional access attention addition opposition opposed '
        'contrast'.split())),
    # Ease, possibility, obligation and plans for an infinitive action.
    (-0.66, frozenset(
        'difficult possible impossible ability unable supposed easy easier hard '
        'harder necessary enough chance willing intended designed required '
        'forced allowed desire attempts trying tend tends needed plans how'.split())),
    (0.75, frozenset({'equivalent'})),
    (-2.0, frozenset({'known'})),
    (-0.90, frozenset('is was are were be'.split())),
    (-1.38, frozenset('and or but'.split())),
)


def english_to(previous):
    word = previous.strip().lower()
    if word.startswith(('relat', 'refer', 'correspond', 'connect', 'attach',
                        'belong', 'commit', 'dedicat', 'subject', 'adapt', 'link')):
        return -0.04
    if word.startswith('compar'):
        return -0.20
    if word.startswith(('contribut', 'respond', 'response')):
        return 0.30
    for strength, words in TO_CONSTRUCTIONS:
        if word in words:
            return strength
    if word and all(not c.isalnum() for c in word):
        return -1.29
    if word.isdigit():
        return -1.15
    if word.endswith(('ed', 'ing')):
        return -0.93
    return -1.01


def spelling_value(token):
    word = token.strip()
    lower = word.lower()
    spaced = token[:1].isspace()
    if lower == 'to':
        if spaced:
            return -1.60 if word == 'To' else -1.28
        return -1.76 if word == 'to' else -1.90
    if lower in ('into', 'onto', 'unto'):
        if spaced:
            return {'into': -0.05, 'onto': -0.53, 'unto': -1.09}[lower]
        return -0.90
    if lower.endswith('to') and lower not in ('auto', 'goto'):
        letters = ''.join(c for c in lower if c.isalpha())
        if letters == 'to':
            return -2.30
        if letters.endswith('proto'):
            return -2.35
        if letters == 'oto':
            return -2.45
        if len(letters) <= 3:
            return -1.26
        return -0.71 if len(letters) == 4 else -0.30
    # Conversion names, such as toString or ToArray.
    if word.startswith(('To', 'to', '.To', '.to')):
        if word.lstrip('.')[2:] in ('String', 'Array', 'Json', 'Lower', 'Props', 'Item'):
            return -1.25
    # Japanese 'to': strongest alone, weaker in compound expressions.
    if word == 'と':
        return -4.27
    if word in ('ト', 'ﾄ'):
        return -2.0
    if word in ('」と', 'ると', 'だと', 'っと', 'ッと', 'すると'):
        return -2.95
    if word in ('ないと', 'になると', 'ようと', 'しようと', '人と'):
        return -2.0
    if word.endswith('こと'):
        return -0.65
    if word.startswith('として'):
        return -2.2 / len(word)
    if word.startswith('とな'):
        return -0.8 / (len(word) - 2) ** 0.5 if len(word) > 2 else -2.0
    if word.startswith('と') and word not in ('とき', 'とても', 'とにかく'):
        return -1.35 if len(word) == 2 and word not in ('とは', 'との') else -4.0 / len(word)
    if lower == 'то':
        return -1.86 if spaced else -2.10
    if word == 'تو':
        return -1.1 if spaced else -2.0
    if word == '토':
        return -1.35
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, last_word = ('', '') if carry is None or carry[0] != document else carry[1:]
    token = prefix.token_strings[-1]
    if token == ' to':
        value = english_to(previous)
    elif token == 'to' and previous.isspace():
        value = english_to(last_word)
    else:
        value = spelling_value(token)
    last_word = last_word if token.isspace() else token
    return (document, token, last_word), float(value)

programs.haiku:
"""Detector for the word "to" (and its fragments), negative in most uses.

The component is negative on "to" when "to" opens an infinitive or a purpose clause:
"known to", "instructed to", "sure to", "and to", "To build ...". It is most negative
after punctuation or a conjunction, and at the start of a sentence; after other words
(verbs, nouns, adjectives, pronouns) it is moderately negative. It is weaker after
"able", "order", "way". It is near zero after "need", "want", "have", "going" and after
relation words that take a "to" meaning "in relation or response to" ("related to",
"in response to", "according to", "close to", "return to"). After "due", "equal",
"equivalent", "contribute", "prior" it is slightly positive.

Other "to"-like pieces push it negative too: the Japanese particle と, the Russian
то, and short fragments ending in "to" (such as "-to", "_to", "oto"). Everything
else is about zero.
"""

READS = ()

# "to" after these is a relation or response preposition, not an infinitive: near zero.
RELATION = {"related", "relating", "relate", "relates", "close", "closer", "up",
            "attention", "access", "addition", "back", "similar", "compared", "leading",
            "led", "lead", "leads", "response", "respond", "responded", "thanks", "owing",
            "opposed", "pertaining", "corresponds", "corresponding", "proportional",
            "return", "subject", "respect", "regard", "according"}
# "to" after these (need to, want to, have to, going to) is near zero.
MODAL = {"need", "needs", "want", "wants", "have", "has", "going"}
# "to" after these is slightly positive: due to, equal to, prior to, contribute to.
POSITIVE = {"due", "equal", "equivalent", "contribute", "contributes", "contribution", "prior"}
# "to" after these is weakly negative.
WEAK = {"able", "order", "way", "ways", "wanted", "go", "come", "get", "needed",
        "applied", "approach", "changes", "referred", "meant"}
# "to" after punctuation or a conjunction is strongly negative.
BREAKS = {",", ".", "and", "or", "but", ")", "-"}
FOREIGN = {"と", "ト", "то"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in FOREIGN:
        return carry, -3.5
    if word != "to":
        if word.endswith("to") and len(word) <= 3:
            return carry, -1.8
        return carry, 0.0
    if prefix.position == 0:
        return carry, -1.0
    prev = prefix.token_strings[-2].strip().lower()
    if prev in POSITIVE:
        return carry, 0.3
    if prev in RELATION or prev in MODAL:
        return carry, 0.0
    if prev in WEAK:
        return carry, -0.3
    if prev in BREAKS:
        return carry, -1.4
    if prev == "":
        return carry, -1.6
    return carry, -0.9

