"""Ampersands and some forms of character encoding.

Single ampersands and HTML reference openings produce positive responses;
logical AND is weaker. Marked Latin vowels also respond, especially isolated
letters with tildes or double acute accents. Tilde vowels with extra marks
and short accented word fragments receive smaller responses. An eight-character
suffix recognizes hexadecimal escapes and the first digits of numeric HTML
references, resetting at document boundaries.
For a split Unicode character, its completed form is read from decoded text.
The mojibake sequence Ã followed by control U+0083 is also strong.
"""
import unicodedata
from functools import lru_cache

READS = ()

# Response to an isolated vowel carrying a tilde, by its base letter.
TILDE_VOWELS = {'a': 2.1, 'A': 1.7, 'e': 1.8, 'i': 0.43,
                'o': 4.1, 'O': 3.9, 'u': 1.5}


@lru_cache(maxsize=4096)
def marked_vowel(token):
    word = token.strip()
    if not word:
        return 0.0
    decomposed = unicodedata.normalize('NFD', word)
    base = decomposed[0]
    if len(word) == 1:
        marks = decomposed[1:]
        if '\u0303' in marks:
            value = TILDE_VOWELS.get(base, 0.0)
            if base == 'A' and token[:1].isspace():
                value = 1.25
            return value * (0.2 if len(marks) > 1 else 1.0)
        if '\u030b' in marks:
            return 2.75 if base.lower() == 'o' else 0.63
        if '\u0302' in marks:
            return {'a': 0.72, 'o': 0.3, 'u': 0.22}.get(base.lower(), 0.0)
        if '\u030a' in marks:
            return 0.4 if base.lower() == 'a' else 0.25
    elif len(word) == 2:
        if '\u030b' in decomposed:
            return 1.1
        if word[0] in 'ãõ':
            return 0.3
    elif len(word) == 3 and '\u030b' in decomposed:
        return 0.32
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    last = before.rstrip()[-1:]
    state = (doc, (before + token)[-8:])
    if '&' in token or '＆' in token:
        if '&&' in token:
            value = 0.1 if '\n' in token else 0.29
        elif '&#' in token:
            value = 1.15 if '>' in token else (1.4 if last.isdigit() else 1.7)
        elif '&amp' in token:
