            value = 1.08
    elif token == '2' and before.endswith('\\xe'):
        value = 0.45
    elif before.endswith('\\xc') and token in ('2', '4'):
        value = 0.7 if token == '2' else 1.0
    elif token == '3' and before.endswith('&#'):
