"""Local English 'in' phrases, especially 'in ... case' and 'in front of'.

Case and front have weak negative baselines and stronger pulses after
'in', reduced when a token intervenes. A following 'of' gets a pulse too.
Several common spatial and discourse expressions beginning with 'in'
get weaker responses. Capitalized 'In' changes their response strengths.
The determiner immediately after 'in' also gets a small, signed pulse.
This approximation leaves unrelated vocabulary at zero.
"""
READS = ()

# Response at 'case' in 'in <determiner> case'.
CASE_DETERMINERS = {
    'this': -0.51, 'the': -0.59, 'a': -0.57,
    'that': -0.72, 'which': -0.73, 'any': -0.66,
    'each': -0.49, 'our': -0.47, 'either': -0.64,
}
# Familiar expressions: value on their second word, immediately after 'in'.
IN_EXPRESSIONS = {
    'recent': -0.50, 'reality': -0.51, 'between': -0.28,
    'view': -0.25, 'theory': -0.28, 'practice': -0.25,
    'general': -0.12, 'fact': -0.11, 'short': -0.23,
    'order': -0.08, 'response': -0.15, 'question': -0.23,
    'need': -0.26, 'middle': -0.28, 'future': -0.32,
    'compliance': -0.28, 'search': -0.22,
    'line': 0.28, 'turn': 0.17, 'addition': 0.12,
    'other': -0.15, 'all': -0.21, 'such': -0.19,
    'each': 0.20, 'that': 0.15, 'which': 0.07,
    'their': 0.12, 'your': 0.12, 'her': 0.11, 'its': 0.12,
    'his': 0.06, 'my': -0.07, 'our': -0.04,
    'any': -0.05, 'many': -0.08, 'no': -0.15,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, older, pulse = '', '', '', 0.0
    else:
        _, previous, before_previous, older, pulse = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    prev_in = previous in {'in', 'In'}
    earlier_in = before_previous in {'in', 'In'}
    capital_in = previous == 'In' if prev_in else before_previous == 'In'
    value = 0.0
    if word == 'case':
        value = -0.06
        if prev_in:
            value = -1.10
            if before_previous.lower() == 'just':
                value = -1.29
        elif earlier_in:
            value = CASE_DETERMINERS.get(previous, -0.50)
        elif older in {'in', 'In'}:
            value = -0.30
        if (prev_in or earlier_in) and capital_in:
            value -= 0.06 if earlier_in else 0.14
    elif word == 'cases':
        value = -0.035
        if prev_in:
            value = -0.55
        elif earlier_in:
            value = -0.29
    elif word == 'front':
        value = -0.18
        if prev_in:
            value = -0.90 - (0.10 if capital_in else 0.0)
        elif earlier_in:
            value = -0.48
    elif word == 'of' and previous in {'case', 'cases', 'front'}:
        if previous == 'front':
            value = -0.31 if pulse > -0.4 else pulse - 0.11
        else:
            value = -0.24 + 0.50 * (pulse + 0.06)
    elif prev_in and word in IN_EXPRESSIONS:
        value = IN_EXPRESSIONS[word]
        if capital_in:
            if word == 'other':
                value -= 0.19
            elif word in {'all', 'such'}:
                value -= 0.10
            elif value < 0:
                value -= 0.07
            elif word != 'addition':
                value += 0.05
    return (doc, word, previous, before_previous, value), float(value)

