"""'In case' / 'in front' detector, with the 'of' after them, at half strength.

Activation is strongly negative on the head noun of the fixed phrases "in case",
"in front", "in spite", "in reality", "in recent ...", and weakly negative on the
"of" that follows them ("in front of", "in case of") or a spatial word ("outside of").
Everywhere else it is 0, apart from a few weak positive words.
"""
READS = ()
HEAD = {"case", "cases", "front", "reality", "spite", "recent"}
PHRASE_OF = {"case", "front", "spite", "reality"}
SPATIAL_OF = {"inside", "outside", "vicinity", "north", "south", "east", "west", "rear", "house", "benefit", "respect", "advance", "honor", "pursuit"}
POSITIVE = {"new", "its", "including", "each", "your"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in HEAD:
        return carry, (-0.5 if prev == "in" else -0.25)
    if word == "of":
        if prev in PHRASE_OF:
            return carry, -0.3
        if prev in SPATIAL_OF:
            return carry, -0.1
    if word in POSITIVE:
        return carry, 0.025
    return carry, 0.0

