"""Estimate number activations, with a stronger response to dates after months."""

import re

READS = ()

MONTHS = {
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
    "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep",
    "sept", "oct", "nov", "dec",
}

NUMBER_START = {
    "0": 0.28, "1": 0.45, "2": 0.60, "3": 0.26, "4": 0.27,
    "5": 0.33, "6": 0.15, "7": 0.21, "8": 0.20, "9": 0.11,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    history, old_doc = carry if carry is not None else ("", doc)
    if old_doc != doc:
        history = ""

    leading = token.lstrip()
    first = leading[:1]
    has_space_prefix = len(leading) < len(token)
    begins_number = bool(first) and first.isdecimal()
    space_before = has_space_prefix or bool(history and history[-1].isspace())
    context = history + token[:len(token) - len(leading)]
    match = re.search(r"([^\W\d_]+)\s*$", context)
    word_before = match.group(1).lower() if match else ""

    value = 0.0
    if begins_number and space_before:
        if word_before in MONTHS:
            value = 1.30
        elif word_before == "in":
            value = 0.65
        else:
            value = NUMBER_START.get(first, 0.10)
    elif begins_number and history and history[-1] in ",.:;(/+-":
        value = 0.12

    history = (history + token)[-48:]
    return (history, doc), float(value)

programs.sol:
"""Detect periods, especially periods attached to closing punctuation.

A bare period is stronger after a number.  A period sharing its token with
brackets, quotes, or a mathematical symbol is much stronger.  An attached
newline suppresses this response. Bare periods are also stronger in
number- and punctuation-heavy documents, and weaker later in a document
or in the first few tokens of a line (such as numbered list markers).
Ordinary words receive zero; their smaller lexical effects are omitted.
All running counts reset at document boundaries.
"""

from math import log1p

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0, 0.0, 0.0, 0)
    _, previous, position, digits, punctuation, line_tokens = carry
    width = max(len(text), 1)
    carry = (
        document, text, position + 1,
        digits + sum(c.isdigit() for c in text) / width,
        punctuation + sum(not c.isalnum() and not c.isspace()
                          for c in text) / width,
        int(bool(text.rsplit('\n', 1)[-1])) if '\n' in text
        else line_tokens + 1,
    )
    stripped = text.strip()
    numeric = previous[-1:].isdigit()

    if stripped == '.':
        if '\n' in text:
            value = -0.035 - 0.025 * (text.count('\n') > 1)
            value += 0.12 * numeric
            value += 0.20 * text.startswith(' ')
        elif text.startswith(' '):
            value = 0.60 if previous[-1:].isalnum() else 0.26
        else:
            previous_punctuation = (bool(previous)
                                    and not previous[-1].isalnum()
                                    and not previous[-1].isspace())
            value = (0.355 - 0.047 * log1p(position) + 0.217 * numeric
                     + 0.324 * previous_punctuation
                     - 0.087 * previous.startswith(' ')
                     + 0.20 * (digits + punctuation) / max(position, 1)
                     - 0.286 * (line_tokens < 3))
            if position == 0:
                value = 0.02
        return carry, value

    if stripped.endswith('.') and not any(c.isalnum() for c in stripped):
        before = stripped[:-1]
        if not before or before.endswith('.') or len(before) > 4:
            return carry, 0.0  # Ignore ellipses and long decoration runs.
        last = before[-1]
        if last in ')]':
            value = 0.97 if last == ')' else 1.06
        elif last == '}':
            value = 1.43
        elif last in '\"\'`”’»“':
            value = 1.65
        elif last == '$':
            value = 1.07
        elif last == '%':
            value = 2.00
        elif last == '/':
            value = 3.90
        elif last in '*_':
            value = 2.85 if last == '*' else 2.55
        else:
            value = 2.40
        value += 0.34 * (len(before) - 1)
        value += 0.40 * before.endswith(('()', '[]', '{}'))
        value += 0.35 * text.startswith(' ')
        if '\n' in text:
            value *= 0.33 if text.count('\n') == 1 else 0.23
        return carry, value

    if stripped.startswith('.,'):
        return carry, -0.22
    if stripped.endswith('。'):
        if len(stripped) > 1 and stripped[-2] in '”’」』':
            return carry, 0.94 if '\n' not in text else 0.25
        if len(stripped) > 1 and stripped[-2] in '）)]':
            return carry, 0.66 if '\n' not in text else 0.18
        return carry, -0.10 if '\n' not in text else 0.0
    return carry, 0.0

