programs.sol:
"""Approximate a negative response to forward-slash boundaries.

Slash-prefixed words are strongest; bare slashes and their next tokens are
weaker. Whitespace, short word length, and a preceding slash adjust strength.
Comments, URL schemes, and closing tags have separate, weaker responses.
Unit abbreviations are stronger; runtimes and familiar root paths are weaker.
Adjacent `}{` braces get a small negative value, a proxy for LaTeX fractions.

Only the previous token is remembered, resetting at document boundaries.
The rules leave out fine token-specific strengths and longer context.
"""
READS = ()
MASS_LENGTH_UNITS = {'cm', 'mm', 'km', 'kg', 'mg'}
RUNTIMES = {
    'java', 'python', 'go', 'javascript', 'typescript',
    'ruby', 'php', 'perl', 'node', 'bash',
}
ROOT_DIRS = {'workspace', 'testbed', 'usr', 'opt', 'home', 'tmp'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    s = text.strip()
    p = previous.strip()
    value = 0.0
    if '/' in s or '／' in s:
        # Slash syntax inside the current token.
        if '</' in s:
            value = -0.14 if s.endswith('</') else 0.0
        elif '://' in s:
            value = -0.5
        elif s.startswith('//'):
            value = -0.15 if text.startswith(' ') else -0.4
        elif '*/' in s:
            value = -0.05 if '\n' in text else -0.25
        elif s.startswith('/*'):
            value = -0.8 if text.startswith(' ') else -1.1
        elif s.startswith('/>'):
            value = -0.9
        elif s in ('/', '／'):
            value = -2.1
            if text == '/' and '/' in p:
                value += 0.4
            elif text == '/' and previous[:1].isspace() and p.isalpha():
                value -= 0.5
            if text.startswith(' '):
                value += 0.35
            if '\n' in text:
                value += 0.6
                if text.count('\n') > 1:
                    value += 0.6
        elif s.startswith('/') and s[1:].isalpha():
            word = s[1:]
            lower = word.lower()
            value = -4.45 if len(word) <= 3 else -4.05
            if previous[:1].isspace() and p.isalpha():
                value -= 0.65
            if lower in MASS_LENGTH_UNITS:
                value = -5.6
            elif lower in RUNTIMES:
                value = -3.2
            elif lower in {'or', 'and'} and p.lower() in {'and', 'or'}:
                value = -3.4
            elif lower in ROOT_DIRS:
                value = -3.6
            elif lower in {'bin', 'sbin'}:
                value = -3.3
            if '/' in p and not p.startswith('<'):
                value += 0.55 if len(word) == 1 else 1.2
            if p in {'/bin', '/sbin'} and lower in RUNTIMES:
                value = -0.7
        elif s.startswith('/') and s[1:] in ('_', '__'):
            value = -3.2
        elif s.startswith('/@'):
            value = -3.8
        elif s.startswith('/('):
            value = -2.45
        elif s.startswith('/'):
            value = -2.1
        else:
            value = -1.15 if any(c in s for c in "'\".`(") else -1.65
    # Carry a weaker response onto the next token.
    elif s == '}{':
        value = -0.55
    elif p.endswith('</'):
        value = -1.15 if previous.startswith(' ') else -0.9
    elif (p.endswith(('/', '／')) and not p.startswith('//')
          and not any(c in previous for c in ':*<>\n\r')):
        value = -1.05
        if previous.startswith(' '):
            value = -1.65 if s.isalpha() else -1.15
        if text[:1].isspace():
            value = -0.5 if previous.startswith(' ') else -0.3
        elif s.startswith(('.', '-')):
            value = 0.1
    elif (not text[:1].isspace() and p.startswith('/')
          and p[1:].isalpha()):
        if s.startswith(('-', '.')):
            value = 0.2
        elif any(c.isalpha() for c in s) and p[1:].lower() not in RUNTIMES:
            value = -0.3
    return (doc, text), float(value)

