"""Estimate a negative response to slash-based text separators.

Slash chunks attached to letters—common in paths and URLs—get the strongest
response. A bare slash gets a smaller one, and the opening of a code comment
or markup tag gets a mild response. A tag name after a closing-tag mark also
gets a mild response. Other tokens are neutral.
"""
READS = ()
SLASHES = "/／"


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    if any(mark in token for mark in SLASHES):
        suffix = token
        for mark in SLASHES:
            if mark in suffix:
                suffix = suffix.split(mark, 1)[-1]
        if any(char.isalpha() for char in suffix):
            return None, -4.2
        if suffix.startswith("*") or suffix.startswith(">"):
            return None, -0.9
        return None, -2.0
    if len(tokens) > 1:
        previous = tokens[-2]
        if previous.endswith("</") or previous.endswith("}</"):
            return None, -0.9
    return None, 0.0

programs.sol:
"""A token-local center/core/heart detector, with a short after-effect.

Training examples concentrate negative activations on these word families.
Strong negative values mark center/centre and Chinese 中心 (center) or
心 (heart). Related vocabulary gets weaker values. 'Of' after these words
and split center/centre endings inherit a response. Most other tokens get
zero. This detects familiar words and fragments, not arbitrary paraphrases.
"""
READS = ()

# Familiar vocabulary related to centrality and the heart/mind.
INTERIOR_WORDS = {'core', 'cores', 'middle', 'central', 'centralized'}
CENTER_STEMS = {'centr', 'centric', 'centroid', 'centrif', 'eccentric',
                'ентр', 'центр'}
RELATED_WORDS = {'concentration', 'concentrated', 'concentrate', 'concentrating',
                'complex', 'complexes', 'complicated', 'inner', 'hub',
                'psychology', 'psychological', 'carefully'}
CENTER_TRANSLATIONS = {'센터', '중심', 'センター'}  # Korean and Japanese.
SMALL_CENTER_WORDS = {'مركز', 'المركز', 'centro'}  # Arabic and Romance languages.
HEART_TRANSLATIONS = {'cœur', 'corazón', 'coração'}


def lexical(token):
    raw = token.strip()
    word = raw.strip('._:/<>=()-').lower()
    spaced = bool(token and token[0].isspace())
    if word in {'center', 'centre'}:
        if word == 'centre':
            return -5.1
        return -5.95 if spaced else -6.7
    if word in {'centers', 'centres', 'centered', 'centred'}:
        return -4.8
    if word in {'heart', 'hearts', 'heartfelt', 'hearted'}:
        return -2.4 if word == 'heart' else -1.6
    if word == 'cent':  # Also fires on the shared spelling in percent.
        return -1.5 if spaced else -0.7
    if word in INTERIOR_WORDS:
        return -1.05
    if word in CENTER_STEMS or word == 'psych':
        return -1.5
    if word in RELATED_WORDS:
        return -0.75
    if word in {'cluster', 'clusters', 'cardiac', 'cardiovascular'}:
        return -0.55
    if word in {'focus', 'focused'}:
        return -0.3
    if word in CENTER_TRANSLATIONS:
        return -3.9
    if word in SMALL_CENTER_WORDS:
        return -2.5
    if word in HEART_TRANSLATIONS:
        return -1.25
    if word in {'tâm', '심'}:  # Vietnamese heart, Korean heart/core.
        return -3.0
    if word == 'ใจ':  # Thai heart.
        return -0.6
    if word == 'ц' and spaced:  # Cyrillic center-word fragment.
        return -0.67
    if word == 'enter':
        return -0.25 if spaced else -0.9
    if '中心' in raw:
        return -6.7 * 0.7 ** (len(raw) - 2)
    if raw == '心':
        return -4.6
    if raw in {'的心', '内心', '內心', '重心'}:
        return -3.9
    if raw in {'人心', '心里', '心裡', '一心', '用心'}:
        return -3.2
    if any(w in raw for w in {'担心', '擔心', '决心', '決心'}):
        return -0.1
    if any(w in raw for w in {'关心', '關心', '耐心'}):
        return -0.4
    if '心' in raw:
        return -1.7 * 0.8 ** max(0, len(raw) - 2)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().strip('._:/<>=()-').lower()
    value = lexical(token)
    if word == 'of':
        value = 0.6 * lexical(previous)
        if prev in {'heart', 'cent', 'focus'}:
            value = {'heart': -1.78, 'cent': -1.09, 'focus': -0.75}[prev]
    if not token[:1].isspace():
        if prev == 'cent' and word in {'er', 'ers', 'red', 're'}:
            value = -3.2 if word == 're' else -2.5
        elif prev == 'center' and word == 'ing':
            value = -2.2
        elif word == 'enter' and prev.endswith('c'):
            value = -3.8 if prev.endswith('multic') else -1.7
    # A UTF-8 fragment can complete 心 without decoding to it alone.
    if '\ufffd' in token and prefix.text_prefixes[-1].endswith('心'):
        value = -6.3
    return (doc, token), float(value)

