"""Recognize center/core/heart vocabulary and predict its negative activation."""

READS = ()


WORDS = (
    "center", "centre", "central", "centri", "centi",
    "core", "heart", "middle", "nucleus", "kernel",
    "focus", "concentr",
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if any(part in word for part in WORDS):
        return None, -2.0
    if any(part in word for part in ("心", "核心", "集中", "中心", "مركز", "ใจ")):
