programs.sol:
"""A lexical factor detector with a little immediate phrase context.

Factor(s), split fact+oring/f+actor, and Chinese 因素 have large responses.
Causal qualifiers strengthen them; mathematical and molecular qualifiers
weaken them. Related constituent/cause words and overlapping word endings
have smaller responses. 'Of' following factor(s) keeps a strong response.
These rules summarize the largest training responses; unmatched tokens
get zero, omitting many small background responses. State resets per document.
"""
import re

READS = ()
CAUSAL = {'risk', 'key', 'important', 'major', 'relevant', 'environmental',
          'economic', 'social', 'various', 'several', 'other', 'external',
          'many', 'critical', 'human'}
MATHEMATICAL = {'prime', 'constant', 'normalization', 'correction', 'balance',
                'scaling', 'scale', 'scalar'}
VERB_CUES = {'to', 'can', 'could', 'should', 'must', 'me', 'maybe'}
# Small responses to related ideas and to the similar word 'actor'.
RELATED = (
    ({'multiple', 'divisor', 'divisors', 'factorial'}, 0.95),
    ({'element', 'elements', 'reasons', 'multiples', 'consideration'}, 0.5),
    ({'aspect', 'aspects', 'considerations'}, 0.85),
    ({'criterion', 'criteria', 'influenced'}, 0.65),
    ({'contributor', 'contributors', 'predictor', 'predictors'}, 1.0),
    ({'influence', 'influences', 'contributing', 'force', 'forces'}, 0.4),
    ({'actor', 'actors'}, 1.4),
    ({'fact'}, 0.5),
    ({'reason', 'facts'}, 0.25),
)
# Unspaced factor-/actor-like noun endings and cognate fragments.
ENDINGS = (
    ({'or', 'ore'}, 0.2),
    ({'ator', 'ators', 'ored', 'oring', 'ores', 'tor'}, 0.5),
    ({'ors', 'ctor', 'ctors', 'acter', 'eur', 'oren', 'тор', 'ktor'}, 0.75),
    ({'eurs', 'tors', 'isors', 'akt'}, 1.1),
)
FACTOR = re.compile(r'factor(?:s|ed|ing)?$')
COGNATE = re.compile(r'facteurs?|faktors?|faktoren')
LETTERS = re.compile(r'[a-zA-Z]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False)
    _, previous, tail, previous_factor = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = LETTERS.search(tail + token)
    spelling = match.group()[-24:] if match else ''
    factor = (word in {'factor', 'factors'}
              or bool(FACTOR.fullmatch(spelling.lower())))
    value = 0.0
    if factor:
        if word in {'factor', 'factors'} and token[:1].isspace():
            value = 6.2 if word == 'factor' else 6.6
            if previous in CAUSAL:
                value = 7.5
            elif previous in {'contributing', 'protective', 'significant'}:
                value = 8.5
            elif previous in MATHEMATICAL:
                value = 4.7
            elif previous == 'transcription':
                value = 3.1
            elif previous == 'conversion':
                value = 3.6
            elif previous in VERB_CUES:
                value = 5.0
        elif word in {'factor', 'factors'}:
            value = 5.4 if token[:1].isupper() else 4.8
        elif word.lstrip('_(.') in {'factor', 'factors'}:
            value = 4.5
        else:
            value = 7.1 if tail.endswith('Fact') else 6.1
    elif word.endswith('因素'):
        value = 6.2 if word == '因素' else 5.4
    elif COGNATE.fullmatch(spelling.lower()):
        value = 4.6
    elif word == 'fakt':
        value = 2.0
    elif word.startswith('фактор'):
        value = 5.0
    elif previous.startswith('фактор') and word in {'ы', 'ов', 'а'}:
        value = 3.0
    elif word == '因子':
        value = 4.5
    elif word == '要素':
        value = 2.5
    elif word == '因' or word.endswith('原因'):
        value = 1.6 if word == '因' else 1.3
    elif word in {'受', '受到', '素', '요'}:
        value = 0.95
    elif word == '元素':
        value = 0.5
    elif word.endswith('方面'):
        value = 0.8
    elif word == 'of' and previous_factor:
        value = 1.9 if previous.endswith('s') else 3.2
    else:
        groups = RELATED + (() if token[:1].isspace() else ENDINGS)
        for words, strength in groups:
            if word in words:
                value = strength
                break
        if token in {'actor', 'actors'}:
            value = 2.5
        if word == 'fact' and token.strip().isupper():
            value = 1.4
        elif word.endswith('ufact'):
            value = 1.0
    return (doc, word, spelling, factor), value

