"""Approximate strong “factor” responses and weaker related word responses.

The high-impact examples repeat on “factor(s)” and Chinese factor terms.
Other harvested examples have smaller responses on related words for actors,
aspects, criteria, and elements.
"""
READS = ()

STRONG_FACTOR_WORDS = {
    "factor", "factors", "factored", "factoring", "因素", "要素",
}
SMALL_RELATED_RESPONSES = {
    "actor": 1.4, "actors": 1.4, "acting": 0.5,
    "multiple": 0.9,
    "aspect": 0.8, "aspects": 0.8,
    "criterion": 0.7, "criteria": 0.7,
    "element": 0.65, "elements": 0.75,
    "fact": 0.7, "influenced": 0.65, "influence": 0.65,
    "force": 0.6, "受": 0.9, "方面": 0.65, "元素": 0.6, "因": 1.8,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in STRONG_FACTOR_WORDS:
        value = 6.5
    else:
