programs.sol:
"""A short-fragment spelling detector, strongest on og and Cyrillic ог.

Whitespace/case and fragment length change its strength. Log spellings are
weaker than other short -og pieces; longer og fragments are usually weaker.
Logic/catalog/cogn- stems have intermediate responses. Other text is
predicted as zero, omitting weaker lexical associations. A single g is
boosted when it continues an alphabetic token. State resets at documents.
"""

READS = ()


def response(token, previous=''):
    text = token.strip()
    word = text.lower()
    if word in ('og', 'ог'):
        if token == 'og':
            return 5.0
        if token == 'OG':
            return 4.1
        if token == 'ог':
            return 3.6
        return 2.1 if word == 'og' else 1.0
    if word.strip('.(/=_') == 'log':
        return 2.1 if word == '.log' else 1.5
    if word in ('blog', 'frog'):
        return 0.2
    if word.endswith('og'):
        return 2.8 if len(word) == 3 else 0.8
    if word == 'ogs':
        return 3.2
    if word == 'ogen':
        return 2.0
    if word in ('ogn', 'ogue'):
        return 2.5
    if word.startswith('og') and token == text:
        return 1.4 if len(word) <= 4 else 0.5
    if word.startswith(('logic', 'catalog', 'analog')):
        return 0.75
    if word.startswith('cogn'):
        return 2.8 if len(word) <= 4 else 1.2
    if word in ('logs', 'dogs'):
        return 2.2 if word == 'dogs' else 1.3
    if word in ('óg', 'ög', 'oğ'):
        return 1.8
    if word in ('eg', 'ег', 'аг'):
        return 1.0
    if word == 'erg' or word.endswith(('berg', 'burg')):
        return 0.6
    if len(word) <= 4 and word.endswith(('аг', 'ог', 'ег')):
        return 1.0
    if len(word) == 2 and word.endswith('g') and word != 'ng':
        consonant = word[0].isalpha() and word[0] not in 'aeiougn'
        return 0.6 if consonant else 0.25
    if word in ('g', 'г', 'γ', 'گ'):
        inside = token == text and previous[-1:].isalpha()
        return 0.5 if inside else 0.2
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

programs.haiku:
"""layers.0.mlp.down_proj:4410: the "og" spelling detector.

The component writes a large value into the residual stream when the current token
spells the letters o-g as a short chunk of a word: "og", "OG", "dog", "log", "fog",
"cog", "catalog", "analog", "yoga", "eg" and the Cyrillic standalone "ог". Its size
depends on the shape of that chunk, not on the context. It is strongest for a bare
"og" token, then for "dog"-type three-letter words, then for "og" inside short words.
Longer words that happen to contain "og" (technology, Google, photography, ...) barely
respond, and neither do Russian endings such as "ого".

The prediction depends only on the current token's spelling, so it is causal and
needs no carried state. Units are the component's own activation scale.
"""

READS = ()

# Three-letter words built on "og" (consonant + o-g), the "dog" family.
DOG_WORDS = {"dog", "dogs", "cog", "fog", "hog", "jog", "bog", "nog", "sog", "rog", "mog"}


def _word(token):
    """The token's letters only, lowercased (Latin and Cyrillic alike)."""
    return "".join(c for c in token.lower() if c.isalpha())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    if token in ("og", "OG", "Og"):
        value = 5.0
    elif token.strip() in ("og", "OG", "Og"):
        value = 2.0
    elif word == "ог":
        value = 3.5
    elif "og" not in word:
        # Short "eg" fragments and a lone "g" respond weakly.
        if word in ("eg", "ег", "erg"):
            value = 0.4
        elif word == "g":
            value = 0.3
        else:
            value = 0.0
    elif word in DOG_WORDS:
        value = 2.5
    elif "log" in word and len(word) <= 4:
        value = 1.5
    elif len(word) <= 3:
        value = 2.0
    elif len(word) == 4:
        value = 0.7
    else:
        value = 0.25
    return carry, float(value)

"""Directive words. The component turns negative on words about giving orders, decrees,
instructions, authorisations, appointments and recommendations, in English and Chinese.
It is most negative on imperial decree words (命 令 诏 敕) and on inflected directive verbs,
moderately negative on requests, permissions, judgments and similar official acts, and
slightly positive on official titles and legal or government roles."""

READS = ()

# Imperial decree words (Chinese), the strongest responses.
DECREE = set("命令诏敕")
# Directive verbs and nouns, inflected forms: ordered, authorized, recommended, instructions...
DIRECTIVE = {
    "ordered", "orders", "authorized", "authorize", "authorizes", "recommend",
    "recommended", "recommends", "recommending", "recommendation", "recommendations",
    "instruction", "instructions", "instructed", "instruct", "appoint", "appointed",
    "appointment", "appointments", "directive", "directives", "decree", "mandate",
    "mandates", "prescribed", "sentenced", "commanded", "commissioned", "directed",
    "advise", "advised", "advises", "dispatched",
}
# Official acts: requests, petitions, licences, permissions, judgments, approvals.
OFFICIAL = {
    "request", "requests", "requested", "motion", "petition", "petitions", "license",
    "licensed", "licenses", "permission", "judgment", "commission", "approved", "issued",
    "announced", "designated", "nominated", "verdict", "warrant", "sanctioned", "advice",
    "announcement", "designation", "dispatch", "approval",
}
# Everyday words for a command or a requirement: weak.
WEAK = {"order", "command", "commands", "require", "requires", "required", "assign", "assigned"}
# Chinese words for orders, arrangements, decisions and requests: medium.
CHINESE_ACTION = set([
    "判决", "建议", "建議", "推荐", "推薦", "派", "判", "安排", "规定", "規定", "部署", "指定",
    "决定", "決定", "要求", "请求", "請求", "通知", "申请", "禁止", "宣布", "裁",
])
# Official titles and legal or government roles: a small positive response.
ROLES = {
    "lawyer", "lawyers", "counsel", "attorney", "justice", "judges", "chief", "secretary",
    "minister", "affairs", "clerk", "appeals", "supreme", "spokesman", "office", "session",
    "sessions", "meeting", "meetings", "首相", "首席", "副", "秘书长",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    if word in DECREE:
        return carry, -2.7
    if word in DIRECTIVE:
        return carry, -0.8
    if word == "order":
        # "in order to" and "ascending order" are not commands.
        if prev in ("in", "ascending", "decreasing", "inorder"):
            return carry, 0.0
        return carry, -0.5
    if word in CHINESE_ACTION:
        return carry, -0.7
    if word in OFFICIAL:
        return carry, -0.5
    if word in WEAK:
        return carry, -0.23
    if word in ROLES:
        return carry, 0.17
    return carry, 0.0

