READS = ()
# Concept: PHP source code. The component goes negative on the token that opens a PHP
# variable or member name: "$" before a variable, "->" after a variable, "public function".
SIGIL = {' $', '($', ' ($', ' [$', '{$'}
CHAIN = {'()->', "')->", '")->'}
CODE_BEFORE = {' (', ' =', ' =>', ' return', ',', ' .', '(', '=', '[', '{'}
PHP_NAMES = {'php', '.php', 'Illuminate', 'mysqli', 'PDO', 'preg', '_exists', 'strlen', '_rand'}
PHP_MARKS = ('<?php', '$this', '->', 'function', 'echo ', '$_', 'public ', 'array(')
def is_code_before(prev):
    return prev in CODE_BEFORE or prev.strip() == ''
def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ''
    recent = prefix.text_prefixes[-1][-300:]
    php = any(m in recent for m in PHP_MARKS)
    if tok in PHP_NAMES:
        return None, -2.5
    if tok in CHAIN:
        return None, -4.0
    if tok == '->':
        # member access right after a variable such as $this or $request
        near_var = any('$' in t for t in toks[-4:-1])
        return None, (-4.0 if near_var else -1.0)
    if tok == ' $' and is_code_before(prev):
        return None, -2.5
    if tok in SIGIL and php:
        return None, -2.5
    if tok == ' =>' and php:
        return None, -1.3
    if tok == ' function':
        return None, (-4.5 if prev.strip() == 'public' else (-0.5 if php else 0.0))
    return None, 0.0

